window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[356]={"id":"356","numero":356,"titre":"Appendicite","objectifs":[{"id":"356-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","contenu":"<div class=\"notion-course\"><p>Chez l'<span class=\"nc-pink nc-bold\">enfant</span>, le diagnostic d'<span>appendicite</span> est <span>difficile</span> : la présentation varie fortement avec l'<span class=\"nc-red nc-bold\">âge</span> et le risque de retard <span class=\"nc-red nc-bold\">diagnostique</span> expose à la <span><span class=\"nc-red_bg\">perforation</span></span>. La règle clé reste qu'il n'existe <span>pas de parallélisme anatomo-clinique</span> — l'intensité des signes ne préjuge pas du degré de gravité.</p>\n\n      <h5>Symptomatologie selon l'<span class=\"nc-red nc-bold\">âge</span></h5>\n      <table>\n        <thead>\n          <tr><th>Tranche d'âge</th><th>Présentation clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Nourrisson</span></td>\n            <td>Tableau <span><span class=\"nc-red nc-bold\">non</span> <span class=\"nc-red nc-bold\">spécifique</span> et trompeur</span> : <span><span class=\"nc-blue_bg\">AEG</span></span> ; <span><span class=\"nc-blue_bg\">fièvre</span></span> ; <span><span class=\"nc-blue_bg\">vomissements</span></span> ; <span><span class=\"nc-blue_bg\">diarrhée</span></span> ; <span><span class=\"nc-blue_bg\">distension abdominale</span></span> ; <span><span class=\"nc-blue_bg\">déshydratation</span></span> ; <span><span class=\"nc-yellow_bg\">agitation</span></span> et <span><span class=\"nc-yellow_bg\">insomnie</span></span>. <span>Évolution</span> rapide vers la <span><span class=\"nc-red_bg\">perforation</span></span>.</td>\n          </tr>\n          <tr>\n            <td><span>Jeune enfant</span></td>\n            <td>Diagnostic difficile, surtout s'il ne se laisse pas examiner : <span>douleur de localisation peu précise</span> ; <span><span class=\"nc-blue_bg\">fièvre modérée</span></span> ; <span><span class=\"nc-blue_bg\">nausées</span></span> et <span><span class=\"nc-blue_bg\">vomissements</span></span>. Pièges : <span><span class=\"nc-pink nc-bold\">gastro-entérite aiguë</span></span> et <span><span class=\"nc-pink nc-bold\">adénolymphite mésentérique</span></span> retardent le diagnostic.</td>\n          </tr>\n          <tr>\n            <td><span>Grand enfant</span></td>\n            <td>Symptomatologie superposable à celle de <strong>l'adulte</strong> : douleur de la <span>fosse iliaque droite</span>, <span><span class=\"nc-blue_bg\">fièvre</span></span><span class=\"nc-blue_bg\"> modérée</span>, défense au point de <span><span class=\"nc-red_bg nc-bold\">McBurney</span></span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Formes cliniques selon la topographie de l'appendice</h5>\n      <p>La position de l'appendice modifie la présentation et déplace le point douloureux.</p>\n      <table>\n        <thead>\n          <tr><th>Localisation</th><th>Présentation dominante</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red nc-bold\">Latéro-caecale</span></span> (classique)</td><td>Douleur de la <span>fosse iliaque droite</span>, défense au <span><span class=\"nc-red_bg nc-bold\">McBurney</span></span>.</td></tr>\n          <tr><td><span>Rétro-caecale</span></td><td><span><span class=\"nc-red_bg\">Psoïtis</span></span> franc, douleur du <span>flanc droit</span>, <span class=\"nc-red nc-bold\">palper bimanuel</span> en <span class=\"nc-red nc-bold\">décubitus latéral gauche</span>.</td></tr>\n          <tr><td><span>Pelvienne</span></td><td>Douleur hypogastrique, <span>signes urinaires</span> (<span>pollakiurie</span>, <span>dysurie</span>), <span><span class=\"nc-red nc-bold\">ténesme</span></span> et <span class=\"nc-red nc-bold\">faux besoins</span>.</td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Méso-cœliaque</span></span></td><td><span class=\"nc-red_bg\">Tableau d'</span><span><span class=\"nc-red_bg\">occlusion fébrile</span></span> par <span><span class=\"nc-red nc-bold\">iléus</span></span><span class=\"nc-red nc-bold\"> réflexe</span>.</td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Sous-hépatique</span></span></td><td>Tableau pseudo-<span><span class=\"nc-orange_bg\">cholécystite</span></span> : douleur et défense de l'hypochondre droit.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\">Chez le jeune <span class=\"nc-pink nc-bold\">enfant</span>, le diagnostic est souvent retardé et les formes compliquées plus fréquentes ; elles ne sont pas constantes avant six ans.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span>Douleur abdominale</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":1},{"id":"356-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les âges de survenue","contenu":"<div class=\"notion-course\"><p>L'<span>appendicite</span> aiguë peut survenir <strong>à tout âge</strong>, mais sa <span class=\"nc-brown_bg\">fréquence</span> suit une distribution caractéristique.</p>\n      <ul>\n        <li>Pic de <span class=\"nc-brown_bg\">fréquence</span> : de <span><span class=\"nc-yellow_bg nc-bold\">6 ans</span></span> à <span><span class=\"nc-yellow_bg nc-bold\">30-40 ans</span></span>, avec une atteinte maximale chez l'<span><span class=\"nc-pink_bg\">adolescent</span></span> et le <span>jeune adulte</span> (<span>2ᵉ et 3ᵉ décennies</span>).</li>\n        <li><span>Exceptionnelle</span> avant <span>1 an</span> ; <span><span class=\"nc-brown_bg\">rare</span></span><span class=\"nc-brown_bg\"> avant</span> <span>3 ans</span>.</li>\n        <li>La <span class=\"nc-brown_bg\">fréquence</span> <strong><span class=\"nc-brown_bg nc-bold\">décroît avec l'âge</span></strong> au-delà de <span>40 ans</span>, du fait de l'<span><span class=\"nc-brown_bg nc-bold\">involution des tissus lymphoïdes</span></span> appendiculaires.</li>\n        <li>Dans la tranche <span>20-40 ans</span>, légère <span><span class=\"nc-pink nc-bold\">prédominance masculine</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège des âges extrêmes :</strong> chez le <span>nourrisson</span>, la pauvreté des <span>tissus <span class=\"nc-green\">lymphoïdes</span></span> rend l'<span>appendicite</span> <span>rare mais d'emblée grave</span> ; chez le <span>sujet <span class=\"nc-red nc-bold\">âgé</span></span>, une douleur de la <span>fosse iliaque droite</span> impose d'évoquer par principe un <span>cancer du côlon droit</span> avant de retenir une appendicite.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-3","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications chez l’enfant","contenu":"<div class=\"notion-course\"><ul><li>Les complications pédiatriques sont <span class=\"nc-red\">plastron</span>, <span class=\"nc-red\">abcès</span> et <span class=\"nc-red_bg\">perforation</span> avec péritonite localisée ou généralisée ; elles sont particulièrement fréquentes chez le très jeune <span class=\"nc-pink nc-bold\">enfant</span> et lorsque le diagnostic est retardé.</li><li>Ne pas attribuer un taux de <span class=\"nc-red_bg\">perforation</span> de 70–80 % à tous les enfants : il varie fortement avec l’âge et le contexte. Une forme <span class=\"nc-red nc-bold\">non</span> compliquée est possible avant six ans.</li><li>Douleur croissante, altération générale, défense diffuse, <span class=\"nc-blue_bg\">vomissements</span> bilieux ou signes de sepsis imposent une réévaluation urgente et un avis chirurgical.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’intérêt et les limites des examens complémentaires","contenu":"<div class=\"notion-course\"><p>Le diagnostic d'<span>appendicite</span> reste <strong>avant tout clinique</strong>. <span>Les</span> examens complémentaires servent à <strong>conforter</strong> le diagnostic, <strong>éliminer un <span>diagnostic différentiel</span></strong> ou <strong>dépister une <span class=\"nc-red nc-bold\">complication</span></strong> — jamais à remplacer l'examen.</p>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Intérêt</th><th>Limites</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-yellow_bg\">NFS</span></span></td>\n            <td>Marqueur le plus souvent perturbé : <span>hyperleucocytose à PNN</span> dans plus de <span>80 %</span> des cas.</td>\n            <td>Peut être normale dans <span>les</span> formes débutantes ; <span class=\"nc-red nc-bold\">non</span> <span class=\"nc-red nc-bold\">spécifique</span>.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-yellow_bg\">CRP</span></span></td>\n            <td>Témoigne d'une inflammation évoluant depuis quelques heures.</td>\n            <td><span><span class=\"nc-green nc-bold\">Normale dans 50 %</span></span><span class=\"nc-green nc-bold\"> des cas</span> (<span>appendicite</span> <span class=\"nc-green_bg\">catarrhale</span> débutante).</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-brown_bg\">Bandelette urinaire</span></span></td>\n            <td>Élimine une <span><span class=\"nc-orange_bg\">infection urinaire</span></span>.</td>\n            <td>Une <span>leucocyturie</span> modérée peut accompagner une <span>appendicite</span> pelvienne (piège).</td>\n          </tr>\n          <tr><td colspan=\"7\">Un test de grossesse fait partie du bilan selon possibilité de grossesse ; sa positivité impose de localiser la grossesse. Le dosage ne permet pas, à lui seul, d’écarter une GEU.</td></tr>\n          <tr>\n            <td><span><span class=\"nc-blue_bg\">Échographie abdominale</span></span></td>\n            <td>Examen de <strong>1ʳᵉ intention</strong> ; <span>Se ≈ 80 %</span> ; non irradiante.</td>\n            <td>Opérateur-dépendante ; mise en défaut chez l'<span>obèse</span> et si appendice <span><span class=\"nc-red nc-bold\">rétro-caecal</span></span>.</td>\n          </tr>\n          <tr>\n            <td><span>TDM abdomino-pelvienne injectée</span></td>\n            <td>Meilleure performance (<span>Se et Sp &gt; 90-95 %</span>) ; précise <span>les</span> complications.</td>\n            <td>Irradiante ; réservée au <span class=\"nc-red nc-bold\">doute</span>, à la <span class=\"nc-red nc-bold\">complication</span>, au <span class=\"nc-red nc-bold\">sujet</span> <span class=\"nc-red nc-bold\">âgé</span> ou obèse.</td>\n          </tr>\n          <tr>\n            <td><span>IRM abdominale</span></td>\n            <td>Alternative non irradiante chez la <span><span class=\"nc-pink nc-bold\">femme</span> <span class=\"nc-pink nc-bold\">enceinte</span></span>.</td>\n            <td>Peu disponible en <span>urgence</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Examens à ne pas demander :</strong> l'<span>ASP</span> n'a plus aucune place dans le bilan d'<span>appendicite</span> ; le dosage de <span>procalcitonine</span> n'est pas recommandé car il n'améliore pas la précision <span class=\"nc-red nc-bold\">diagnostique</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge","contenu":"<div class=\"notion-course\"><ul><li>L’<span class=\"nc-pink_bg\">appendicectomie</span> reste le <span class=\"nc-pink_bg\">traitement</span> de référence. La décision repose sur probabilité clinique, biologie et imagerie adaptée ; toute douleur de fosse iliaque droite n’est pas une indication opératoire.</li><li>Forme non compliquée confirmée : prise en charge chirurgicale précoce, généralement dans les 24 heures selon organisation. Péritonite, sepsis ou instabilité : urgence renforcée, réanimation et contrôle de foyer sans retard.</li><li>Mesures initiales : jeûne, antalgie suffisante, hydratation adaptée, antibiotiques selon forme et protocole, consultation anesthésique.</li><li>Certaines formes non compliquées sélectionnées ou abcès/plastrons peuvent relever d’un traitement initial non opératoire ; bénéfices, récidive et surveillance sont discutés par l’équipe. Ne pas présenter cette option comme adaptée à tous ni comme inexistante.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":1},{"id":"356-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la symptomatologie de l’appendicite chez le nourrisson","contenu":"<div class=\"notion-course\"><p>Chez le <span>nourrisson</span>, la présentation est <span><span class=\"nc-red nc-bold\">non</span> <span class=\"nc-red nc-bold\">spécifique</span> et <span class=\"nc-red nc-bold\">trompeuse</span></span>. C'est ce qui fait toute la <span>gravité</span> de la pathologie à cet âge : le diagnostic est porté <span>tardivement</span>.</p>\n      <ul>\n        <li><span>Altération de l'état général</span> (<span>AEG</span>).</li>\n        <li><span><span class=\"nc-blue_bg\">Fièvre</span></span> et <span><span class=\"nc-blue_bg\">vomissements</span></span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Diarrhée</span></span> — qui oriente faussement vers une <span>gastro-entérite</span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Distension abdominale</span></span> et <span><span class=\"nc-blue_bg\">déshydratation</span></span>.</li>\n        <li><span><span class=\"nc-yellow_bg\">Agitation</span></span> et <span><span class=\"nc-yellow_bg\">insomnie</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">Chez le nourrisson, une suspicion persistante impose des réévaluations rapprochées et un avis chirurgical ; ne pas proposer d’attendre plusieurs jours devant des signes de <span class=\"nc-red nc-bold\">complication</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span>Douleur abdominale</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-7","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’appendicite aiguë","contenu":"<div class=\"notion-course\"><p>L'<span>appendicite aiguë</span> est une <strong>inflammation aiguë de l'appendice vermiforme</strong>, le plus souvent secondaire à une <strong>obstruction de la lumière appendiculaire</strong>.</p>\n\n      <h5>Causes de l'obstruction appendiculaire</h5>\n      <table>\n        <thead>\n          <tr><th>Cause</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red nc-bold\">Stercolithe</span></span></td><td>Concrétion dure de matières fécales obstruant la lumière (cause la plus classique).</td></tr>\n          <tr><td><span>Hyperplasie lymphoïde</span></td><td>Réaction des <span class=\"nc-green\">follicules</span> <span class=\"nc-green\">lymphoïdes</span> à un <span class=\"nc-red nc-bold\">épisode</span> <span><span class=\"nc-red nc-bold\">viral</span></span><span class=\"nc-red nc-bold\"> ou bactérien du tube digestif</span>.</td></tr>\n          <tr><td><span>Infection parasitaire</span></td><td>Obstruction mécanique (ascaris).</td></tr>\n          <tr><td><span><span class=\"nc-brown_bg\">Sténose inflammatoire</span></span></td><td>Épaississement pariétal dans la maladie de <span><span class=\"nc-red nc-bold\">Crohn</span></span>.</td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Tumeur</span></span></td><td>Occlusion par une <span class=\"nc-red nc-bold\">tumeur</span>, le plus souvent <span>carcinoïde</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h5><span>Physiopathologie</span> en 4 temps</h5>\n      <ol>\n        <li>L'obstruction entraîne une <strong>pullulation microbienne</strong> responsable de l'infection de l'appendice.</li>\n        <li>L'inflammation s'étend progressivement aux <strong><span class=\"nc-orange_bg\">4 couches pariétales</span></strong> : c'est l'<span><span class=\"nc-red nc-bold\">appendicite suppurée</span></span>.</li>\n        <li>La distension comprime la vascularisation et entraîne une <span><span class=\"nc-red nc-bold\">ischémie artérielle</span></span>.</li>\n        <li>En l'absence de traitement, l'<span>évolution</span> se fait vers la <span><span class=\"nc-purple nc-bold\">gangrène</span></span> puis la <span><span class=\"nc-red nc-bold\">perforation</span></span>.</li>\n      </ol>\n\n      <h5>Rappel anatomique</h5>\n      <table>\n        <thead>\n          <tr><th>Élément</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Organe</strong></td><td><span>Diverticule</span> appendu au <strong>cæcum</strong>, riche en <span>tissu lymphoïde</span> ; longueur moyenne <span><span class=\"nc-pink nc-bold\">8 cm</span></span> (<span>2 à 20 cm</span>), épaisseur <span><span class=\"nc-green_bg\">4 à 8 mm</span></span>.</td></tr>\n          <tr><td><strong>Paroi en 4 couches</strong></td><td><span class=\"nc-purple_bg\">Séreuse externe</span> ; <span class=\"nc-purple_bg\">musculeuse</span> ; <span class=\"nc-purple_bg\">sous-muqueuse</span> (riche en <span><span class=\"nc-green\">follicules</span> <span class=\"nc-green\">lymphoïdes</span></span>) ; <span class=\"nc-purple_bg\">muqueuse</span> délimitant la lumière.</td></tr>\n          <tr><td><strong>Vascularisation</strong></td><td><span><span class=\"nc-pink nc-bold\">Artère appendiculaire</span></span>, <span class=\"nc-pink_bg\">branche terminale de l'artère iléo-colique</span> — vascularisation de <strong>type terminal</strong>, d'où le risque d'<span>ischémie</span>.</td></tr>\n          <tr><td><strong>Implantation</strong></td><td>Zone de convergence des <strong>3 bandelettes musculaires longitudinales</strong> du côlon droit, à environ <span>2 cm</span> de la valvule iléo-cæcale.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Formes anatomopathologiques :</strong> formes <span class=\"nc-red nc-bold\">non</span> compliquées — <span><span class=\"nc-green_bg\">catarrhale</span></span> (<span class=\"nc-purple_bg\">muqueuse</span> seule), <span><span class=\"nc-green_bg\">suppurée</span></span>, <span><span class=\"nc-green_bg\">gangréneuse</span></span> ; formes compliquées — <span><span class=\"nc-red\">abcès</span></span>, <span><span class=\"nc-red\">plastron</span></span>, <span>péritonite</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-8","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence, l’âge de survenue et la morbi-mortalité et la mortalité de l’appendicite","contenu":"<div class=\"notion-course\"><p>L'<span>appendicite</span> aiguë est l'<span><span class=\"nc-yellow_bg\">urgence abdominale la plus fréquente</span></span>.</p>\n      <ul>\n        <li><strong>Fréquence :</strong> concerne environ <span>7 %</span> de la population dans <span>les</span> pays occidentaux, dont <span>20 %</span> de <span>formes compliquées</span>.</li>\n        <li><strong>Volume d'activité :</strong> environ <span>90 000 à 130 000</span> <span>appendicectomies</span> par an en France (<span>≈ 1,4 / 1 000 habitants</span>), soit <span>≈ 30 %</span> des interventions de <span>chirurgie</span> digestive.</li>\n        <li><strong>Âge :</strong> pic de <span class=\"nc-brown_bg\">fréquence</span> de <span><span class=\"nc-yellow_bg nc-bold\">6 ans</span></span> à <span><span class=\"nc-yellow_bg nc-bold\">30-40 ans</span></span> ; exceptionnelle avant <span>1 an</span>, <span class=\"nc-brown_bg\">rare avant</span> <span>3 ans</span> ; décroît ensuite avec l'âge.</li>\n      </ul>\n\n      <h5>Morbi-<span>mortalité</span></h5>\n      <table>\n        <thead>\n          <tr><th>Indicateur</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Mortalité</span> post-opératoire globale</td><td><span>&lt; 0,5 %</span></td></tr>\n          <tr><td><span>Mortalité</span> — forme non compliquée</td><td><span>≈ 0,1 %</span></td></tr>\n          <tr><td><span>Mortalité</span> — <span>perforation appendiculaire</span></td><td><span>≈ 1,5 %</span></td></tr>\n          <tr><td><span>Morbidité</span> globale des <span>appendicectomies</span></td><td><span>≈ 10 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong><span>Évolution</span> des pratiques :</strong> l'<span><span class=\"nc-pink_bg\">appendicectomie</span></span> était autrefois quasi <span class=\"nc-red nc-bold\">systématique</span> devant toute douleur de la <span>fosse iliaque droite</span> ; elle n'est aujourd'hui réalisée qu'au terme d'une démarche <span class=\"nc-red nc-bold\">diagnostique</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","contenu":"<div class=\"notion-course\"><p>Le tableau typique de l'<span>appendicite</span> aiguë associe une <strong>douleur</strong> caractéristique, des <strong>signes digestifs</strong> et un <strong><span class=\"nc-blue_bg\">fébricule</span></strong>, confirmés par l'examen de la <span>fosse iliaque droite</span>.</p>\n\n      <h5>Caractéristiques de la douleur appendiculaire</h5>\n      <table>\n        <thead>\n          <tr><th>Caractère</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Mode de début</td><td><span>Brutal</span>.</td></tr>\n          <tr><td>Topographie</td><td><span class=\"nc-blue_bg\">Peut débuter en région </span><span><span class=\"nc-blue_bg\">épigastrique</span></span> ou <span><span class=\"nc-blue_bg\">péri-ombilicale</span></span>, puis <strong>migre en fosse iliaque droite</strong> <span class=\"nc-pink nc-bold\">en quelques heures</span>.</td></tr>\n          <tr><td><span>Irradiation</span></td><td>Absente.</td></tr>\n          <tr><td>Horaire</td><td><span><span class=\"nc-yellow_bg\">Permanente</span></span>, d'intensité <strong>croissante</strong> sur <span>les</span> premières <span>24 h</span>.</td></tr>\n          <tr><td>Type</td><td>À type de <span>torsion</span> ou de <span>crampe</span>.</td></tr>\n          <tr><td>Facteurs aggravants</td><td>Majorée par <span>les</span> <span><span class=\"nc-red nc-bold\">mouvements</span></span>, la <span><span class=\"nc-red nc-bold\">toux</span></span> et le <span><span class=\"nc-red nc-bold\">cloche-pied droit</span></span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Signes associés</h5>\n      <ul>\n        <li><strong>Signes digestifs :</strong> <span><span class=\"nc-blue_bg\">nausées</span></span> ; <span><span class=\"nc-blue_bg\">vomissements</span></span> ; <span><span class=\"nc-brown_bg\">inappétence</span></span> ; <span><span class=\"nc-brown_bg\">diarrhée</span></span><span class=\"nc-brown_bg\"> rare</span>.</li>\n        <li><strong>Signes généraux :</strong> <span><span class=\"nc-blue_bg\">fébricule</span></span> à <span>37,5-38,5 °C</span> (dans <span>60 %</span> des cas), parfois absent ; <span class=\"nc-brown_bg\">signes de </span><span><span class=\"nc-brown_bg\">déshydratation</span></span> dans <span>les</span> formes évoluées (<span>tachycardie</span>, <span>pli cutané</span>, <span>langue saburrale</span>).</li>\n      </ul>\n\n      <h5>Examen physique de la fosse iliaque droite</h5>\n      <p>Rechercher les cicatrices et antécédents chirurgicaux. Une <span class=\"nc-pink_bg\">appendicectomie</span> antérieure oriente vers d’autres causes mais n’exclut pas totalement une rare appendicite du moignon.</p>\n      <table>\n        <thead>\n          <tr><th>Manœuvre</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Point de <span class=\"nc-red_bg nc-bold\">McBurney</span></span></td><td>Douleur provoquée (<span>sensibilité</span> ou <span>défense</span>) au 1/3 externe de la ligne reliant l'épine iliaque antéro-supérieure droite à l'ombilic.</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Signe de Blumberg</span></span></td><td>Douleur en FID à la <span>décompression brutale de la FID</span> (inconstant).</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Signe de Rovsing</span></span></td><td>Douleur en FID provoquée par la <span>compression de la fosse iliaque gauche</span> (inconstant).</td></tr>\n          <tr><td><span><span class=\"nc-red_bg\">Psoïtis</span></span></td><td><span><span class=\"nc-red nc-bold\">Boiterie</span></span>, <span class=\"nc-green_bg\">cuisse droite fléchie en position </span><span><span class=\"nc-green_bg\">antalgique</span></span> ; l'<span class=\"nc-red nc-bold\">extension de la cuisse sur le bassin</span> majore la douleur.</td></tr>\n          <tr><td><span><span class=\"nc-yellow_bg\">Heel drop test</span></span></td><td>Douleur abdominale déclenchée par la retombée sur les talons : signe d’irritation péritonéale à interpréter avec l’ensemble de l’examen, sans valeur suffisante pour confirmer ou exclure seul une appendicite.</td></tr>\n          <tr><td><span>Toucher <span class=\"nc-red nc-bold\">rectal</span></span></td><td>Douleur latéralisée à droite (« cri du Douglas ») ; le toucher vaginal est déconseillé chez l'enfant.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"appendix-figure\">\n        \n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span>Douleur abdominale</span> aiguë</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":2},{"id":"356-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","contenu":"<div class=\"notion-course\"><p>Certains signes négatifs permettent d'<strong>écarter</strong> une <span>appendicite</span> et d'orienter vers un <span>diagnostic différentiel</span> — étape essentielle pour ne pas opérer à tort.</p>\n\n      <div class=\"callout callout-info\">L’absence conjointe de signes inflammatoires et de défense diminue fortement la probabilité, surtout après un délai d’évolution suffisant ; elle n’exclut pas une forme très précoce. Donner des consignes de réévaluation et surveiller si le <span class=\"nc-red nc-bold\">doute</span> persiste.</div>\n\n      <h5><span>Score</span> d'Alvarado — aide à l'orientation</h5>\n      <p>Aucun <span>score</span> n'est validé pour la pratique courante, mais le score d'Alvarado constitue une <strong>aide à l'orientation</strong> de la prise en charge.</p>\n      <table>\n        <thead>\n          <tr><th>Item</th><th>Points</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Douleur migrant en FID</span></td><td><span>1</span></td></tr>\n          <tr><td><span>Anorexie</span></td><td><span>1</span></td></tr>\n          <tr><td><span><span class=\"nc-blue_bg\">Nausées</span> / <span class=\"nc-blue_bg\">vomissements</span></span></td><td><span>1</span></td></tr>\n          <tr><td><span>Température &gt; 37,3 °C</span></td><td><span>1</span></td></tr>\n          <tr><td><span>Défense en FID</span></td><td><span>2</span></td></tr>\n          <tr><td><span>Défense à la percussion de la FID</span></td><td><span>1</span></td></tr>\n          <tr><td><span>Hyperleucocytose &gt; 10 000/mm³</span></td><td><span>2</span></td></tr>\n          <tr><td><span>Neutrophiles &gt; 75 %</span></td><td><span>1</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><span>0–4</span> : <span>appendicite</span> <strong>improbable</strong>.</li>\n        <li><span>5–6</span> : <span>appendicite</span> <strong>possible</strong>.</li>\n        <li><span>7–8</span> : <span>appendicite</span> <strong>probable</strong>.</li>\n        <li><span>9–10</span> : <span>appendicite</span> <strong>très probable</strong>.</li>\n      </ul>\n\n      <h5>Principaux diagnostics différentiels</h5>\n      <table>\n        <thead>\n          <tr><th>Contexte</th><th>Diagnostics à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Enfant</span></td>\n            <td><strong><span class=\"nc-pink nc-bold\">Adénolymphite mésentérique</span></strong> : cause la plus fréquente de syndrome pseudo-appendiculaire (antécédent <span class=\"nc-orange_bg\">de rhino-pharyngite</span>, <span><span class=\"nc-blue_bg\">fièvre</span></span> <span class=\"nc-blue_bg nc-bold\">&gt;</span><span><span class=\"nc-blue_bg nc-bold\"> 39 °C</span></span>, douleur <span class=\"nc-blue_bg\">sans défense</span>) ; <strong><span class=\"nc-red_bg\">invagination intestinale aiguë</span></strong> ; <strong><span class=\"nc-pink nc-bold\">gastro-entérite aiguë</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><span>Femme en âge de procréer</span></td>\n            <td><span><span class=\"nc-red_bg\">Salpingite</span></span> — <span>douleurs hypogastriques</span> + <span>syndrome <span>infectieux</span></span> + pertes vaginales + douleur au <span>TV</span> ; écho pelvienne : <span><span class=\"nc-red nc-bold\">épaississement</span></span> et <span><span class=\"nc-red nc-bold\">aspect en roue dentée</span></span>. <span><span class=\"nc-red_bg\">Torsion d'annexe</span></span> ; <span><span class=\"nc-red_bg\">grossesse extra-utérine</span></span> ; <span><span class=\"nc-red_bg\">ovulation douloureuse</span></span> ; <span><span class=\"nc-red_bg\">endométriose</span></span> — d'où la <span><span class=\"nc-pink nc-bold\">β-hCG</span></span> et l'<span class=\"nc-blue_bg\">examen gynécologique</span> systématiques.</td>\n          </tr>\n          <tr>\n            <td><span>Urinaire</span></td>\n            <td><span>Colique néphrétique</span> ; <span>pyélonéphrite aiguë</span> — la <span><span class=\"nc-brown_bg\">bandelette urinaire</span></span> oriente.</td>\n          </tr>\n          <tr>\n            <td><span>Digestif</span></td>\n            <td><strong><span><span class=\"nc-red_bg\">Diverticulite</span></span><span class=\"nc-red_bg\"> de Meckel</span></strong> ; <strong>appendalgite</strong> (torsion d'une frange épiploïque colique) ; <span>diverticulite du côlon droit</span> ou <span>diverticulite sigmoïdienne</span> avec boucle localisée en <span class=\"nc-blue_bg\">FID</span> ; <span><span class=\"nc-orange_bg\">cholécystite</span> aiguë</span> ; <span>MICI</span> (<span class=\"nc-orange\">Crohn</span> ++) ; <span><span class=\"nc-red nc-bold\">tumeur</span> du côlon droit</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Trois pièges à connaître</h5>\n      <ul>\n        <li><strong><span class=\"nc-pink nc-bold\">Adénolymphite mésentérique</span> :</strong> <span><span class=\"nc-blue_bg\">fièvre</span></span> élevée et douleur de FID <span><span class=\"nc-blue_bg\">sans défense</span></span> ; l'<span><span class=\"nc-blue_bg\">échographie</span></span> montre des <span>adénopathies</span> mésentériques et un appendice normal.</li>\n        <li><strong><span>Diverticule</span> de Meckel :</strong> diverticule du <span class=\"nc-yellow_bg nc-bold\">bord antimésentérique de l'iléon terminal</span>, pouvant contenir une <span class=\"nc-yellow_bg nc-bold\">muqueuse gastrique ectopique</span> ; diagnostic souvent peropératoire.</li>\n        <li><strong>Appendalgite :</strong> torsion d'une frange épiploïque ; douleur de FID <span>sans <span class=\"nc-blue_bg\">hyperleucocytose</span> ni signe infectieux</span> ; <span class=\"nc-pink_bg\">traitement</span> par <span class=\"nc-pink_bg\">anti-inflammatoires</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span>Douleur abdominale</span> aiguë · 287 — Diverticulose colique - <span>diverticulite</span> aiguë · 277 — Lithiase biliaire · 265 — Lithiase urinaire · 161 — <span><span class=\"nc-orange_bg\">Infection urinaire</span></span> · 25 — <span><span class=\"nc-red_bg\">Grossesse</span></span><span class=\"nc-red_bg\"> extra-utérine</span> · 282 — <span>MICI</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/meckel-diverticulum-3?lang=us","label":"Radiopaedia : Meckel diverticulum 3"}]},{"id":"356-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les variations anatomiques de l’appendice et les formes cliniques qui en résultent","contenu":"<div class=\"notion-course\"><p><span>Les</span> variations de position de l'<span>appendice vermiforme</span> (et du cæcum) sont fréquentes et expliquent l'extrême variabilité des présentations cliniques.</p>\n\n      <h5><span class=\"nc-brown_bg\">Fréquence</span> des localisations anatomiques</h5>\n      <table>\n        <thead>\n          <tr><th>Localisation</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red nc-bold\">Latéro-caecale</span></span> (face postéro-médiale du cæcum)</td><td><span>≈ 70 %</span></td></tr>\n          <tr><td><span>Rétro-caecale</span></td><td><span>≈ 25 %</span></td></tr>\n          <tr><td><span>Pelvienne</span></td><td><span>≈ 5 %</span></td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Méso-cœliaque</span></span> (pré- ou rétro-iléale) et <span><span class=\"nc-red nc-bold\">sous-hépatique</span></span></td><td>Rares</td></tr>\n          <tr><td>Fosse iliaque gauche (<span>mésentère commun</span>)</td><td>Exceptionnelle</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Formes cliniques résultant de la topographie</h5>\n      <table>\n        <thead>\n          <tr><th>Localisation</th><th>Présentation</th><th>Confirmation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Rétro-caecale</span></td>\n            <td><span><span class=\"nc-red_bg\">Psoïtis</span></span> franc ; douleur peu marquée en FID, plutôt en <span>flanc droit</span> ; <span class=\"nc-red nc-bold\">palper bimanuel</span> en <span class=\"nc-red nc-bold\">décubitus latéral gauche</span>.</td>\n            <td><span><span class=\"nc-blue_bg\">TDM injectée</span></span></td>\n          </tr>\n          <tr>\n            <td><span>Pelvienne</span></td>\n            <td>Douleur hypogastrique droite ; <span>signes urinaires</span> (<span>pollakiurie</span>, <span>dysurie</span>) ; <span><span class=\"nc-red nc-bold\">ténesme</span> <span class=\"nc-red nc-bold\">rectal</span></span> et <span class=\"nc-red nc-bold\">faux besoins</span> ; toucher <span class=\"nc-red nc-bold\">rectal</span> et vaginal contributifs.</td>\n            <td><span><span class=\"nc-blue_bg\">Échographie pelvienne</span></span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Méso-cœliaque</span></span></td>\n            <td><span class=\"nc-red_bg\">Tableau d'</span><span><span class=\"nc-red_bg\">occlusion fébrile</span></span> par <span><span class=\"nc-red nc-bold\">iléus</span></span><span class=\"nc-red nc-bold\"> réflexe</span> au <span>contact</span> des anses.</td>\n            <td><span>Imagerie</span> voire intervention</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Sous-hépatique</span></span></td>\n            <td>Tableau pseudo-<span><span class=\"nc-orange_bg\">cholécystite</span></span> : douleur et défense de l'hypochondre droit avec <span><span class=\"nc-blue_bg\">fièvre</span></span>.</td>\n            <td><span>Échographie</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège :</strong> la forme <span class=\"nc-red nc-bold\">méso-cœliaque</span> réalise un véritable tableau de syndrome occlusif fébrile qui peut faire errer le diagnostic.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les particularités de la présentation clinique de l’appendicite chez la femme enceinte","contenu":"<div class=\"notion-course\"><p>Chez la <span>femme <span class=\"nc-pink nc-bold\">enceinte</span></span>, la présentation dépend du <strong>terme</strong> de la <span>grossesse</span>, l'utérus gravide refoulant progressivement l'appendice.</p>\n      <table>\n        <thead>\n          <tr><th>Terme</th><th>Présentation clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>1ᵉʳ trimestre</span></td>\n            <td>Examen clinique <strong>non modifié</strong> : tableau d'<span>appendicite</span> en situation normale.</td>\n          </tr>\n          <tr>\n            <td><span>2ᵉ et 3ᵉ trimestres</span></td>\n            <td>L'<span>augmentation du volume utérin</span> <strong>refoule l'<span>appendice</span> vers l'<span>hypochondre droit</span></strong> (vers le <strong>haut</strong>, le <strong>dehors</strong> et l'<strong>arrière</strong>) : <span><span class=\"nc-blue_bg\">douleur ascensionnée</span></span><span class=\"nc-blue_bg\"> ou </span><span><span class=\"nc-blue_bg\">diffuse</span></span> ; <span><span class=\"nc-blue_bg\">contractures utérines</span></span> parfois au premier plan ; <span><span class=\"nc-green nc-bold\">absence de défense</span></span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Diagnostics différentiels :</strong> <span><span class=\"nc-orange_bg\">infection urinaire</span></span> ; <span><span class=\"nc-orange_bg\">cholécystite</span></span>.</li>\n        <li><strong>Imagerie :</strong> l'<span>IRM abdominale</span> est <span>préférée à la TDM</span> (caractère <span>non irradiant</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège :</strong> l'<span><span class=\"nc-green nc-bold\">absence de défense</span></span> aux 2ᵉ et 3ᵉ trimestres ne doit jamais faire éliminer une <span>appendicite</span> — la <span>position ectopique de l'appendice</span> masque <span>les</span> <span>signes pariétaux</span> classiques.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-13","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les particularités de la présentation clinique de l’appendicite chez le sujet âgé","contenu":"<div class=\"notion-course\"><p>Chez le <span>sujet <span class=\"nc-red nc-bold\">âgé</span></span>, l'<span>appendicite</span> est <span>plus rare</span> mais souvent <span>diagnostiquée tardivement</span>, à un <span>stade compliqué</span>.</p>\n      <ul>\n        <li><span>Symptômes <span class=\"nc-red nc-bold\">moins</span> <span class=\"nc-red nc-bold\">francs</span></span> que chez l'<span>adulte jeune</span>.</li>\n        <li><span>Évolution <span class=\"nc-red nc-bold\">plus torpide</span></span>.</li>\n        <li><span>Iléus</span> fréquemment présent.</li>\n        <li><span>Indice de perforation élevé</span> (<span>≈ 30 %</span>) du fait du <span>retard diagnostique</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">Chez le <span class=\"nc-pink nc-bold\">sujet âgé</span>, rechercher une <span class=\"nc-red nc-bold\">tumeur</span> cæcale et les autres diagnostics, sans retarder le traitement d’une appendicite compliquée. Organiser les explorations coliques adaptées après l’<span class=\"nc-red nc-bold\">épisode</span> si indiquées.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","contenu":"<div class=\"notion-course\"><ul><li><span class=\"nc-red\">Plastron</span> : masse inflammatoire périappendiculaire sans collection drainable ; <span class=\"nc-red\">abcès</span> : collection <span class=\"nc-green_bg\">suppurée</span> ; péritonite : diffusion péritonéale, parfois avec sepsis. L’imagerie précise le contrôle de foyer possible.</li><li><span class=\"nc-red\">Plastron</span> ou abcès bien limité chez un patient stable : <span class=\"nc-pink_bg\">antibiothérapie</span> et discussion d’un drainage accessible ; chirurgie immédiate ou différée selon situation et expertise. Une appendicectomie <span class=\"nc-red nc-bold\">systématique</span> à trois mois n’est pas une règle universelle.</li><li>Péritonite ou instabilité : traitement urgent médicochirurgical. L’absence habituelle de pneumopéritoine dans la perforation appendiculaire ne signifie pas qu’il soit impossible.</li><li>Prélever selon contexte, adapter antibiothérapie et durée à la forme, au contrôle du foyer et à l’évolution ; pas de trois hémocultures imposées à toute fièvre ni de durée unique pour tous les abcès.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":1},{"id":"356-15","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques à demander et leurs limites","contenu":"<div class=\"notion-course\"><p>Le bilan <span>biologique</span> de l'<span>appendicite</span> est <strong>simple</strong> et son apport reste limité : il conforte le diagnostic et écarte certains différentiels, mais ne le pose jamais à lui seul.</p>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Résultat attendu</th><th>Limite</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-yellow_bg\">NFS</span></span></td>\n            <td><span>Hyperleucocytose à PNN</span> (<span>&gt; 10 000/mm³</span>) dans plus de <span>80 %</span> des cas — marqueur le plus souvent perturbé.</td>\n            <td>Peut être <span>normale</span> dans <span>les</span> formes débutantes ; <span><span class=\"nc-red nc-bold\">non</span> <span class=\"nc-red nc-bold\">spécifique</span></span>.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-yellow_bg\">CRP</span></span></td>\n            <td>Élevée si l'inflammation évolue depuis quelques heures.</td>\n            <td><span><span class=\"nc-green nc-bold\">Normale dans 50 %</span></span><span class=\"nc-green nc-bold\"> des cas</span> (<span>appendicite <span class=\"nc-green_bg\">catarrhale</span></span> débutante).</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-brown_bg\">Bandelette urinaire</span></span></td>\n            <td>Utile pour <strong>éliminer une</strong> <span><span class=\"nc-orange_bg\">infection urinaire</span></span>.</td>\n            <td>Une <span>leucocyturie</span> modérée n'exclut pas une <span>appendicite pelvienne</span>.</td>\n          </tr>\n          <tr><td colspan=\"7\">Un test de grossesse fait partie du bilan selon possibilité de grossesse ; sa positivité impose de localiser la grossesse. Le dosage ne permet pas, à lui seul, d’écarter une GEU.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À ne pas demander :</strong> le dosage de la <span>procalcitonine</span> n'est <strong>pas recommandé</strong> — il n'améliore pas la précision du diagnostic d'<span>appendicite</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":0},{"id":"356-16","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens d’imagerie à demander et leurs limites","contenu":"<div class=\"notion-course\"><p>L'<span class=\"nc-green nc-bold\">imagerie</span> confirme le diagnostic, recherche une <span class=\"nc-red nc-bold\">complication</span> et élimine <span>les</span> diagnostics différentiels. L'<span><span class=\"nc-blue_bg\">échographie</span></span> est l'examen de 1ʳᵉ intention, la <span><span class=\"nc-blue_bg\">TDM</span></span> le plus performant.</p>\n\n      <h5><span><span class=\"nc-blue_bg\">Échographie</span></span> <span>vs</span> <span><span class=\"nc-blue_bg\">TDM</span></span> abdomino-pelvienne</h5>\n      <table>\n        <thead>\n          <tr><th>Item</th><th><span><span class=\"nc-blue_bg\">Échographie abdominale</span></span></th><th><span>TDM</span>-AP injectée (temps <span class=\"nc-red nc-bold\">portal</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Indication</td>\n            <td>Examen de <strong>1ʳᵉ intention</strong></td>\n            <td><strong><span class=\"nc-red nc-bold\">Complication</span></strong>, <strong><span class=\"nc-red nc-bold\">doute</span> <span class=\"nc-red nc-bold\">diagnostique</span></strong>, <span><span class=\"nc-red nc-bold\">sujet</span> <span class=\"nc-red nc-bold\">âgé</span></span> ou <span>obèse</span></td>\n          </tr>\n          <tr>\n            <td>Performance</td>\n            <td><span>Sensibilité ≈ 80 %</span></td>\n            <td><span>Se et Sp &gt; 90-95 %</span> — meilleur examen</td>\n          </tr>\n          <tr>\n            <td><span>Critères diagnostiques</span></td>\n            <td><span>Diamètre</span> <span><span class=\"nc-pink nc-bold\">≥ 6 mm</span></span> ; paroi <span><span class=\"nc-pink nc-bold\">&gt; 3 mm</span></span> ; appendice <span><span class=\"nc-orange nc-bold\">incompressible</span></span> et <span class=\"nc-orange nc-bold\">douloureux au passage de la sonde</span> ; <span><span class=\"nc-blue_bg\">aspect en cocarde</span></span> ; <span>perte de la différenciation des couches pariétales</span> ; <span>infiltration</span> <span class=\"nc-blue nc-bold\">hyperéchogène</span> de la graisse ; <span class=\"nc-red nc-bold\">stercolithe</span> avec cône d'ombre</td>\n            <td>Appendice augmenté de calibre, <span class=\"nc-red nc-bold\">épaississement</span>/rehaussement pariétal, infiltration de graisse et éventuel <span class=\"nc-red nc-bold\">stercolithe</span>. Aucun signe isolé ni seuil de diamètre ne suffit ; l’infiltration peut manquer à un stade précoce.</td>\n          </tr>\n          <tr>\n            <td>Limites</td>\n            <td>Opérateur-dépendante ; mise en défaut chez l'obèse et si appendice <span class=\"nc-red nc-bold\">rétro-caecal</span></td>\n            <td>Irradiante ; produit de contraste iodé</td>\n          </tr>\n          <tr>\n            <td>Délai</td>\n            <td>Disponible et rapide</td>\n            <td><span><span class=\"nc-pink nc-bold\">&lt; 24 h</span></span> sans gravité ; <span><span class=\"nc-pink nc-bold\">&lt; 4 h</span></span> si <span>signes de gravité</span> ou <span><span class=\"nc-red nc-bold\">terrain</span></span> <span class=\"nc-red nc-bold\">fragile</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Quand demander l'<span class=\"nc-green nc-bold\">imagerie</span> — stratégie HAS 2012</h5>\n      <table>\n        <thead>\n          <tr><th>Probabilité</th><th>Critères</th><th>Conduite</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Faible</td>\n            <td>Absence de la triade : pas de <span><span class=\"nc-blue_bg\">défense en FID</span></span>, pas d'<span><span class=\"nc-blue_bg\">hyperleucocytose</span></span>, <span><span class=\"nc-blue_bg\">CRP</span> <span class=\"nc-green nc-bold\">&lt; 8 mg/L</span></span></td>\n            <td>Faible probabilité : surveillance et réévaluation selon évolution ; une biologie normale très précoce ne suffit pas à exclure le diagnostic.</td>\n          </tr>\n          <tr>\n            <td>Intermédiaire</td>\n            <td>Un ou deux éléments de la triade seulement</td>\n            <td><span>Imagerie morphologique</span> au minimum (écho ou <span>TDM</span>) ; <span>hospitalisation</span> prolongée avant décision</td>\n          </tr>\n          <tr>\n            <td>Forte</td>\n            <td>Triade complète : <span><span class=\"nc-blue_bg\">défense en FID</span></span> + <span><span class=\"nc-blue_bg\">hyperleucocytose</span> <span class=\"nc-red nc-bold\">&gt; 10 G/L</span></span> + <span><span class=\"nc-yellow_bg\">CRP</span> <span class=\"nc-red nc-bold\">&gt; 8 mg/L</span></span></td>\n            <td><strong>Homme <span class=\"nc-pink nc-bold\">jeune</span> :</strong> <span class=\"nc-pink_bg\">appendicectomie</span> d'emblée ; <strong><span class=\"nc-pink nc-bold\">femme</span> <span class=\"nc-pink nc-bold\">jeune</span> ou sujet <span class=\"nc-red nc-bold\">âgé</span> / obèse :</strong> <span class=\"nc-green nc-bold\">imagerie</span> d'abord pour écarter <span>les</span> différentiels</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Complications visibles à l'<span class=\"nc-green nc-bold\">imagerie</span></h5>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Complications recherchées</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Échographie</span></td>\n            <td><span>Épanchement liquidien</span> ; <span>abcès</span> (ainsi que <span>nécrose</span> et <span><span class=\"nc-red\">plastron</span></span> selon le collège de pédiatrie).</td>\n          </tr>\n          <tr>\n            <td><span>TDM-AP injectée</span></td>\n            <td><span>Abcès</span> ; <span>épanchement péri-hépatique</span> ; <span>épanchement du cul-de-sac de Douglas</span> ; <span>épanchement de la cavité péritonéale</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Autres examens d'<span class=\"nc-green nc-bold\">imagerie</span></h5>\n      <ul>\n        <li>IRM sans gadolinium si nécessaire pendant la grossesse après échographie <span class=\"nc-red nc-bold\">non</span> concluante ; distinguer les risques des différents produits de contraste. Le contraste iodé concerne la TDM, pas l’IRM.</li>\n        <li><strong>Cœlioscopie exploratrice :</strong> proposée chez la <span><span class=\"nc-pink nc-bold\">femme</span> <span class=\"nc-pink nc-bold\">jeune</span></span> si <span class=\"nc-green nc-bold\">imagerie</span> <span class=\"nc-green nc-bold\">non</span> <span class=\"nc-green nc-bold\">contributive</span>, après <strong><span class=\"nc-green nc-bold\">avis</span> <span class=\"nc-green nc-bold\">gynécologique</span></strong>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>À ne plus demander :</strong> l'<span>ASP</span> n'a plus aucune place dans le bilan <span class=\"nc-red nc-bold\">diagnostique</span> de l'<span>appendicite</span>.</div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/acute-appendicitis-2?lang=us","label":"Radiopaedia : Acute appendicitis 2"}]},{"id":"356-17","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","contenu":"<div class=\"notion-course\"><ul><li>Appendicite non compliquée : <span class=\"nc-pink_bg\">appendicectomie</span>, habituellement par cœlioscopie, après diagnostic suffisamment étayé et préparation anesthésique. Antalgie, hydratation adaptée et antibioprophylaxie selon protocole.</li><li>Analyse anatomopathologique de la pièce pour confirmer et rechercher une tumeur. Pas de drainage ou de lavage péritonéal <span class=\"nc-red nc-bold\">systématique</span> d’une forme simple.</li><li>Après contrôle d’une appendicite non compliquée, ne pas prolonger systématiquement les antibiotiques 24–48 heures au titre d’une prophylaxie. Reprise alimentaire et sortie selon récupération clinique.</li><li>Surveiller <span class=\"nc-blue_bg\">fièvre</span>, douleur persistante, abcès, saignement et troubles du transit. Les complications tardives comprennent occlusion sur bride et, rarement, appendicite du moignon.</li><li>Une stratégie par antibiotiques seuls peut être discutée chez certains patients sélectionnés, avec information sur échec/récidive ; elle ne se substitue pas au contrôle urgent d’une forme compliquée.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/douleurs-abdominopelviennes\" target=\"_blank\" rel=\"noopener noreferrer\">Collège de pédiatrie · douleurs abdominopelviennes, occlusion, appendicite, hernie</a></li><li><a href=\"https://sfar.org/antibioprophylaxie-en-chirurgie-et-medecine-interventionnelle/\" target=\"_blank\" rel=\"noopener noreferrer\">SFAR–SPILF · antibioprophylaxie en chirurgie</a></li></ul></details>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> le traitement de l'<span class=\"kw-clinique\">appendicite</span> est <em>toujours</em> <span class=\"kw-ttt\">chirurgical</span> et réalisé <span class=\"kw-alerte\">en urgence</span>, en raison du <span class=\"kw-alerte\">risque d'évolution vers une forme compliquée</span> (<span class=\"kw-clinique\">abcès</span>, plastron, <span class=\"kw-clinique\">péritonite</span>).</p><p><strong>Forme non compliquée <span class=\"q\">— sans <span class=\"kw-alerte\">signe de gravité</span></span></strong></p><p><span class=\"kw-imagerie\">imagerie</span> (<span class=\"kw-imagerie\">échographie</span> / <span class=\"kw-imagerie\">TDM</span>) réalisée en <span class=\"kw-chiffre\">&lt; 24 h</span></p><ul><li><span class=\"kw-ttt\">Appendicectomie</span> dans un délai <span class=\"kw-chiffre\">&lt; 24 h</span></li></ul><p><strong><span class=\"kw-alerte\">Signes de gravité</span> ou <span class=\"kw-def\">terrain</span> fragile <span class=\"q\">— enfant, sujet âgé</span></strong></p><p><span class=\"kw-imagerie\">imagerie</span> réalisée en <span class=\"kw-chiffre\">&lt; 4 h</span></p><ul><li><span class=\"kw-ttt\">Appendicectomie</span> dans un délai <span class=\"kw-chiffre\">&lt; 4 h</span></li></ul><p><strong><span class=\"kw-clinique\">Péritonite</span> appendiculaire généralisée <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> chirurgicale absolue</span></strong></p><p>aucun examen d'imagerie supplémentaire si tableau typique → bloc immédiat</p><ul><li><span class=\"kw-alerte\">Défense généralisée voire contracture</span> + <span class=\"kw-clinique\">fièvre &gt; 38,5 °C</span></li></ul>","hospit":"<p><strong>Tableau typique</strong></p><ul><li><span class=\"kw-ttt\">Intervention</span> programmée au plus vite après <span class=\"kw-ttt\">consultation d'anesthésie</span> en <span class=\"kw-alerte\">urgence</span></li></ul><p><strong>Tableau incomplet / diagnostic douteux</strong></p><ul><li><span class=\"kw-imagerie\">TDM</span> + <span class=\"kw-clinique\">hospitalisation pour surveillance</span> (durée allongée avant décision)</li></ul><p><strong>Absence de la tétrade <span class=\"q\">— pas de défense, ni hyperleucocytose, ni <span class=\"kw-clinique\">fièvre</span>, ni <span class=\"kw-bio\">CRP</span></span></strong></p><ul><li>Diagnostic <span class=\"kw-alerte\">écarté</span></li></ul><p><strong>Nourrisson / jeune enfant</strong></p><ul><li><span class=\"kw-clinique\">Observation</span> de quelques jours possible avant la décision opératoire</li></ul>","redflags":"<ul><li><span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">3 complications</span> : <span class=\"kw-alerte\">abcès</span>, <span class=\"kw-alerte\">plastron</span>, <span class=\"kw-alerte\">péritonite</span> appendiculaire</li><li><span class=\"kw-clinique\">Péritonite</span> : <span class=\"kw-alerte\">faciès gris / terreux</span>, <span class=\"kw-alerte\">défense généralisée voire contracture</span>, <span class=\"kw-clinique\">fièvre &gt; 38,5 °C</span>, <span class=\"kw-clinique\">occlusion fébrile</span></li><li><span class=\"kw-clinique\">Abcès</span> : <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">fièvre &gt; 38,5 °C en plateau</span> + <span class=\"kw-clinique\">syndrome subocclusif</span> (<span class=\"kw-clinique\">iléus</span> réflexe)</li><li>Terrains à <span class=\"kw-alerte\">risque de perforation</span> : <span class=\"kw-etio\">enfant</span> (<span class=\"kw-chiffre\">70-80 %</span>), <span class=\"kw-etio\">sujet âgé</span> (<span class=\"kw-chiffre\">30 %</span>)</li><li>Nourrisson : <span class=\"kw-clinique\">évolution</span> <span class=\"kw-alerte\">rapide vers perforation et péritonite</span> ; <span class=\"kw-clinique\">appendicite</span> <span class=\"kw-alerte\">toujours compliquée avant 6 ans</span>, <span class=\"kw-alerte\">pronostic vital avant 1 an</span></li><li>Sujet âgé : éliminer impérativement une <span class=\"kw-etio\">tumeur colique droite</span></li><li><span class=\"kw-alerte\">Appendicite « toxique »</span> (rare) : translocation <span class=\"kw-etio\">bactérienne</span>, <span class=\"kw-clinique\">évolution</span> possible vers le décès</li></ul>","principes":"<p><strong>Règle d'or :</strong> <span class=\"kw-ttt\">appendicectomie</span> chirurgicale en <span class=\"kw-alerte\">urgence</span> ; <span class=\"kw-ttt\">examen anatomopathologique</span> systématique de la pièce (élimine une tumeur). Le <span class=\"kw-ttt\">traitement médical seul</span> n'est <span class=\"kw-ci\">pas recommandé</span> (en cours d'évaluation).</p><p><strong>Préparation pré-opératoire</strong></p><ul><li>Patient <span class=\"kw-ttt\">à jeun</span></li><li><span class=\"kw-ttt\">Antibiothérapie probabiliste</span></li><li><span class=\"kw-ttt\">Antalgique</span> (<span class=\"kw-ttt\">paracétamol</span> ou phloroglucinol) + <span class=\"kw-ttt\">hydratation IV</span> + correction des troubles hydro-électrolytiques</li></ul><p><strong>Geste : appendicectomie</strong></p><ul><li>Voie d'abord : <span class=\"kw-ttt\">incision de McBurney</span> (laparotomie oblique en FID) ou <span class=\"kw-ttt\">cœlioscopie</span></li><li>Exploration de la cavité péritonéale (prélèvement bactériologique si épanchement)</li><li><span class=\"kw-ttt\">Antibioprophylaxie peropératoire</span> courte (<span class=\"kw-chiffre\">24-48 h</span>) par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span></li><li>Pas de toilette ni de <span class=\"kw-ttt\">drainage</span> péritonéal si forme <span class=\"kw-clinique\">non compliquée</span></li></ul><p><strong><span class=\"kw-clinique\">Péritonite</span> appendiculaire</strong></p><p><span class=\"kw-ttt\">antibiothérapie</span> probabiliste puis adaptée pendant <span class=\"kw-chiffre\">5-7 jours</span></p><ul><li><span class=\"kw-ttt\">Toilette péritonéale</span> + <span class=\"kw-ttt\">drainage</span> + <span class=\"kw-ttt\">appendicectomie</span> en <span class=\"kw-alerte\">urgence</span> (cœlio ou laparotomie)</li></ul><p><strong><span class=\"kw-clinique\">Abcès</span> appendiculaire</strong></p><p><span class=\"kw-ttt\">ATB</span> <span class=\"kw-chiffre\">7 jours</span> + <span class=\"kw-ttt\">appendicectomie à 3 mois</span></p><ul><li><span class=\"kw-ttt\">Drainage percutané radiologique</span> (grande taille) ou <span class=\"kw-ttt\">chirurgical</span> (petite taille / signes péritonéaux)</li></ul><p><strong>Plastron appendiculaire</strong></p><p><span class=\"kw-ttt\">ATB</span> <span class=\"kw-chiffre\">7 jours</span> + <span class=\"kw-ttt\">appendicectomie à 3 mois</span></p><ul><li>Pas de geste de <span class=\"kw-ttt\">drainage</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-etio\">dissection</span> dangereuse, risque de plaie / <span class=\"kw-clinique\">fistule</span> du grêle)</li></ul>","suivi":"<p><strong>Anapath :</strong> <span class=\"kw-ttt\">examen anatomopathologique</span> systématique de la pièce — élimine une tumeur (carcinoïde &gt; adénocarcinome &gt; cystadénocarcinome).</p><p><strong>Suites simples :</strong> reprise de l'<span class=\"kw-clinique\">alimentation le lendemain</span> ; sortie en <span class=\"kw-chiffre\">24-48 h</span> pour <span class=\"kw-clinique\">les</span> formes non compliquées.</p><p><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">&lt; 0,5 %</span> (<span class=\"kw-chiffre\">0,1 %</span> non compliquées · <span class=\"kw-chiffre\">1,5 %</span> perforations) ; <span class=\"kw-def\">morbidité</span> globale <span class=\"kw-chiffre\">10 %</span>.</p><p><strong>Complications post-op :</strong> <span class=\"kw-alerte\">infection du site opératoire</span>, <span class=\"kw-alerte\">abcès du Douglas / péritonite</span> (lâchage du moignon), <span class=\"kw-alerte\">hémorragie</span> / hématome de paroi, <span class=\"kw-alerte\">occlusion du grêle</span> (<span class=\"kw-clinique\">iléus</span> réflexe précoce ; brides / éventration tardives), récidive si moignon trop long.</p><p><strong>Différé :</strong> appendicectomie programmée à <span class=\"kw-chiffre\">3 mois</span> après un <span class=\"kw-clinique\">abcès</span> ou un plastron.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/acute-appendicitis-2?lang=us","label":"Radiopaedia : Acute appendicitis 2"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Douleur de la FID évocatrice d'appendicite — Triade HAS 2012 : défense en FID · hyperleucocytose > 10 G/L · CRP > 8 mg/L","detail":"<h4>CAT — suspicion d'<span class=\"kw-clinique\">appendicite</span> aiguë — Stratification HAS 2012 (probabilité clinico-<span class=\"kw-ttt\">biologique</span>) puis <span class=\"kw-def\">terrain</span></h4>","branches":[{"to":"t-ecarte","label":"Peu probable : aucun des 3 critères (pas de défense, pas d'hyperleucocytose, CRP < 8)","color":"green"},{"to":"t-intermediaire","label":"Probabilité intermédiaire : ni peu probable, ni très probable","color":"amber"},{"to":"q-terrain","label":"Très probable : défense FID + hyperleucocytose > 10 G/L + CRP > 8","color":"red"}]},{"id":"t-ecarte","kind":"terminal","label":"Appendicite écartée → surveillance","color":"green","detail":"<h4>Critères</h4><ul><li>Absence concomitante de <span class=\"kw-clinique\">défense en FID</span></li><li>Absence d'<span class=\"kw-bio\">hyperleucocytose</span></li><li><span class=\"kw-bio\">CRP</span> <span class=\"kw-chiffre\">&lt; 8 mg/L</span></li></ul><h4>CAT</h4><ul><li>Pas de <span class=\"kw-ttt\">chirurgie</span> ni d'imagerie systématique</li><li><span class=\"kw-clinique\">Surveillance</span> ; rechercher un <span class=\"kw-etio\">diagnostic différentiel</span> (<span class=\"kw-bio\">BU</span>, <span class=\"kw-bio\">β-HCG</span> chez la femme en âge de procréer)</li></ul>"},{"id":"t-intermediaire","kind":"terminal","label":"Imagerie + hospitalisation pour surveillance","color":"amber","detail":"<h4>Imagerie</h4><ul><li><span class=\"kw-imagerie\">Échographie abdominale</span> en 1re intention, ou <span class=\"kw-imagerie\">TDM</span> — examen morphologique au minimum</li></ul><h4>CAT</h4><ul><li><span class=\"kw-clinique\">Hospitalisation</span> avec durée de <span class=\"kw-def\">surveillance</span> allongée avant la décision thérapeutique</li></ul>"},{"id":"q-terrain","kind":"decision","label":"Terrain à risque diagnostique ? — Femme en âge de procréer · sujet âgé · obèse","branches":[{"to":"t-chir-emblee","label":"Non — homme jeune, tableau typique","color":"red"},{"to":"t-imagerie-chir","label":"Oui — femme en âge de procréer / sujet âgé / obèse","color":"amber"}]},{"id":"t-chir-emblee","kind":"terminal","label":"Appendicectomie d'emblée","color":"red","detail":"<h4>CAT</h4><ul><li><span class=\"kw-ttt\">Intervention</span> programmée au plus vite après <span class=\"kw-ttt\">consultation d'anesthésie</span> en <span class=\"kw-alerte\">urgence</span> (aucune imagerie indispensable)</li></ul><h4>Pré-opératoire</h4><ul><li>Patient <span class=\"kw-ttt\">à jeun</span>, <span class=\"kw-ttt\">ATB probabiliste</span>, <span class=\"kw-ttt\">antalgique</span> + <span class=\"kw-ttt\">hydratation IV</span></li><li>Délai <span class=\"kw-chiffre\">&lt; 24 h</span> (ou <span class=\"kw-chiffre\">&lt; 4 h</span> si <span class=\"kw-alerte\">signe de gravité</span> / <span class=\"kw-def\">terrain</span> fragile)</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Appendicectomie</span> (McBurney ou cœlioscopie) + <span class=\"kw-ttt\">examen anatomopathologique</span> systématique</li></ul>"},{"id":"t-imagerie-chir","kind":"terminal","label":"Imagerie d'abord puis chirurgie","color":"amber","detail":"<h4>Femme en âge de procréer</h4><ul><li><span class=\"kw-bio\">β-HCG</span> + <span class=\"kw-imagerie\">échographie</span> + examen gynécologique pour écarter une <span class=\"kw-etio\">GEU</span>, une <span class=\"kw-etio\">salpingite</span>, une <span class=\"kw-etio\">torsion d'annexe</span> ; cœlioscopie si imagerie non contributive après avis gynéco</li></ul><h4>Sujet âgé</h4><ul><li><span class=\"kw-imagerie\">TDM</span> systématique : éliminer une <span class=\"kw-etio\">tumeur colique droite</span></li></ul><h4>Obèse</h4><ul><li><span class=\"kw-imagerie\">TDM</span> (<span class=\"kw-imagerie\">échographie</span> peu performante)</li></ul><h4>Puis</h4><ul><li><span class=\"kw-ttt\">Appendicectomie</span> selon <span class=\"kw-clinique\">les</span> résultats de l'imagerie</li></ul>"}]},"cards":[{"i":"102998d35556","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Comment se présente une appendicite chez le grand enfant, par rapport à l'adulte ?","a":"<div class=\"notion-course\"><p>Chez le grand enfant, la symptomatologie de l'appendicite est <strong>superposable à celle de l'adulte</strong>. Elle se caractérise par une <strong>douleur de la fosse iliaque droite</strong>, une <span class=\"nc-blue_bg\">fièvre modérée</span>, et une <strong>défense au point de <span class=\"nc-red_bg nc-bold\">McBurney</span></strong>.</p></div>"},{"i":"48bc2f5591e7","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Comment une appendicite à localisation rétro-caecale peut-elle modifier la présentation clinique ?","a":"<div class=\"notion-course\"><p>Une appendicite à localisation rétro-caecale se manifeste par un <strong><span class=\"nc-red_bg\">psoïtis</span> franc</strong>, une <strong>douleur du flanc droit</strong>. L'examen peut révéler une douleur au <span class=\"nc-red nc-bold\">palper bimanuel</span> en <span class=\"nc-red nc-bold\">décubitus latéral gauche</span>.</p></div>"},{"i":"84e76cf5fe7c","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Quelle est la présentation clinique d'une appendicite sous-hépatique ?","a":"<div class=\"notion-course\"><p>L'appendicite <span class=\"nc-red nc-bold\">sous-hépatique</span> présente un tableau clinique qui simule une <strong>pseudo-<span class=\"nc-orange_bg\">cholécystite</span></strong>, avec une douleur et une défense de l'<strong>hypochondre droit</strong>.</p></div>"},{"i":"8bd7ab9f9983","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Quels sont les signes cliniques distinctifs d'une appendicite à localisation pelvienne ?","a":"<div class=\"notion-course\"><p>Une appendicite à localisation pelvienne se caractérise principalement par une <strong>douleur hypogastrique</strong>, associée à des <strong>signes urinaires</strong> comme la pollakiurie et la dysurie, ainsi que des <strong>ténesmes</strong> et de <strong><span class=\"nc-red nc-bold\">faux besoins</span></strong>.</p></div>"},{"i":"98616b5a2c7a","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Comment se manifeste l'appendicite chez le nourrisson et quels sont les risques associés ?","a":"<div class=\"notion-course\"><p>Chez le nourrisson, la symptomatologie de l'appendicite est <strong><span class=\"nc-red nc-bold\">non</span> <span class=\"nc-red nc-bold\">spécifique</span> et <span class=\"nc-red nc-bold\">trompeuse</span></strong>, incluant un syndrome d'altération de l'état général (<span class=\"nc-blue_bg\">AEG</span>), de la <span class=\"nc-blue_bg\">fièvre</span>, des <span class=\"nc-blue_bg\">vomissements</span>, une <span class=\"nc-blue_bg\">diarrhée</span>, une <span class=\"nc-blue_bg\">distension abdominale</span>, une <span class=\"nc-blue_bg\">déshydratation</span>, ainsi qu'une <span class=\"nc-yellow_bg\">agitation</span> et de l'<span class=\"nc-yellow_bg\">insomnie</span>. L'évolution est rapidement progressive vers la <strong><span class=\"nc-red_bg\">perforation</span></strong>, engageant le pronostic vital avant 1 an.</p></div>"},{"i":"b3f6a66d52e0","n":356,"o":"356-1","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez l’enfant et ses différentes formes cliniques","q":"Quelles sont les particularités cliniques de l'appendicite chez le jeune enfant, et quels sont les pièges diagnostiques ?","a":"<div class=\"notion-course\"><p>Chez le jeune enfant, le diagnostic est difficile, surtout s'il ne se laisse pas examiner. La douleur est de <strong>localisation peu précise</strong>, la <span class=\"nc-blue_bg\">fièvre</span> est modérée, et il y a présence de <span class=\"nc-blue_bg\">nausées</span> et <span class=\"nc-blue_bg\">vomissements</span>. Les pièges diagnostiques classiques qui retardent le diagnostic sont la <strong><span class=\"nc-pink nc-bold\">gastro-entérite aiguë</span></strong> et l'<strong><span class=\"nc-pink nc-bold\">adénolymphite mésentérique</span></strong>.</p></div>"},{"i":"0d44e3d88bc5","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Quel score est parfois utilisé comme aide à l'orientation diagnostique pour une appendicite aiguë, bien qu'il ne soit pas validé pour la pratique courante ?","a":"<div class=\"notion-course\"><p>Il s'agit du score d'<strong>Alvarado</strong>, qui ne doit être utilisé que comme une aide à l'orientation.</p></div>"},{"i":"3d6c2d39b027","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Selon les recommandations de la HAS 2012, quels sont les signes négatifs qui permettent d'écarter le diagnostic d'appendicite aiguë en cas d'absence concomitante ?","a":"<div class=\"notion-course\"><p>Le diagnostic d'appendicite aiguë peut être écarté en l'absence concomitante de :</p><ul><li><strong><span class=\"nc-blue_bg\">Fièvre</span></strong></li><li><strong>Défense en fosse iliaque droite (FID)</strong></li><li><strong>Hyperleucocytose</strong></li><li>Élévation de la <strong>CRP <span class=\"nc-green nc-bold\">&lt; 8 mg/L</span></strong></li></ul></div>"},{"i":"8d5a07e5bef6","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Dans le score d'Alvarado pour l'appendicite aiguë, une défense en fosse iliaque droite (FID) rapporte combien de points ?","a":"<div class=\"notion-course\"><p>Une défense en fosse iliaque droite (FID) rapporte <strong>2 points</strong> dans le score d'Alvarado.</p></div>"},{"i":"ad43351928ba","n":356,"o":"356-10","u":"Diagnostic positif","t":"Connaître les signes cliniques et biologiques en défaveur d’une appendicite aiguë","q":"Selon le score d'Alvarado, à partir de quel intervalle de score l'appendicite est-elle considérée comme « improbable » ?","a":"<div class=\"notion-course\"><p>Une appendicite est considérée comme <strong>improbable</strong> pour un score d'Alvarado de <strong>0 à 4</strong>.</p></div>"},{"i":"9f576a6c85d0","n":356,"o":"356-14","u":"Diagnostic positif","t":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","q":"Quels sont les signes cliniques distinctifs d'un plastron appendiculaire compliqué d'une appendicite, à l'examen physique et biologique ?","a":"<div class=\"notion-course\"><ul><li>Masse inflammatoire périappendiculaire douloureuse, avec <span class=\"nc-red_bg\">empâtement</span> de fosse iliaque droite, fièvre et <span class=\"nc-blue_bg\">syndrome inflammatoire</span> possibles. L’imagerie recherche une collection drainable.</li><li>Une rougeur cutanée n’est pas un critère nécessaire ; les présentations varient avec l’âge et l’évolution.</li></ul></div>"},{"i":"a2be3bfb6312","n":356,"o":"356-14","u":"Diagnostic positif","t":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","q":"Comment différencier cliniquement entre un abcès appendiculaire et un plastron appendiculaire ?","a":"<div class=\"notion-course\"><ul><li>Un abcès est une collection <span class=\"nc-green_bg\">suppurée</span>, le <span class=\"nc-red\">plastron</span> une masse inflammatoire. <span class=\"nc-blue_bg\">Fièvre</span>, douleur, défense et <span class=\"nc-blue_bg\">hyperleucocytose</span> peuvent se chevaucher : l’imagerie est nécessaire pour distinguer et discuter le drainage.</li><li>Une température ou une numération seuil ne suffit pas ; l’absence de frissons ne définit pas l’abcès.</li></ul></div>"},{"i":"ed09a9aac326","n":356,"o":"356-14","u":"Diagnostic positif","t":"Connaître les signes cliniques des trois principales complications de l’appendicite : abcès, plastron, péritonite.","q":"Quels sont les signes cliniques et généraux d'une péritonite appendiculaire généralisée ?","a":"<div class=\"notion-course\"><ul><li>Douleur avec défense/contracture diffuse, altération générale, <span class=\"nc-blue_bg\">fièvre</span> et parfois défaillances d’organe : urgence médicochirurgicale. Les signes peuvent être atténués chez le patient <span class=\"nc-red nc-bold\">fragile</span>.</li><li>Un pneumopéritoine est souvent absent mais reste possible ; son absence ne permet pas d’exclure perforation ou péritonite.</li></ul></div>"},{"i":"12c65e356569","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quels sont les résultats attendus et les limites de la Numération Formule Sanguine (NFS) dans le diagnostic de l'appendicite aiguë ?","a":"<div class=\"notion-course\"><p>Dans l'appendicite aiguë, la <span class=\"nc-yellow_bg\">NFS</span> révèle une <strong>hyperleucocytose à polynucléaires neutrophiles (PNN &gt; 10 000/mm³)</strong> dans plus de 80 % des cas. C'est le marqueur le plus souvent perturbé.</p><ul><li><strong>Limites :</strong> Elle peut être normale dans les formes débutantes et n'est pas <span class=\"nc-red nc-bold\">spécifique</span> du diagnostic d'appendicite.</li></ul></div>"},{"i":"45c9ce430116","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Le dosage de la procalcitonine est-il recommandé dans la suspicion d'appendicite aiguë selon les référentiels de l'EDN ?","a":"<div class=\"notion-course\"><p><span class=\"nc-red nc-bold\">Non</span>, le dosage de la <strong>procalcitonine</strong> n'est <strong>pas recommandé</strong> dans le bilan <span class=\"nc-red nc-bold\">diagnostique</span> de l'appendicite aiguë, car il n'améliore pas la précision du diagnostic.</p></div>"},{"i":"6b47981c20e7","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quels sont l'intérêt et les limites de la CRP et de la bandelette urinaire dans le bilan d'une appendicite aiguë ?","a":"<div class=\"notion-course\"><ul><li>La <strong><span class=\"nc-yellow_bg\">CRP</span></strong> est élevée si l'inflammation évolue depuis quelques heures, mais est <span class=\"nc-green nc-bold\">normale dans </span><strong><span class=\"nc-green nc-bold\">50% des cas</span></strong> d'appendicite <span class=\"nc-green_bg\">catarrhale</span> débutante.</li><li>La <strong><span class=\"nc-brown_bg\">bandelette urinaire</span></strong> est utile pour <strong>éliminer une <span class=\"nc-orange_bg\">infection urinaire</span></strong>, mais une <strong>leucocyturie modérée</strong> n'exclut pas une appendicite pelvienne.</li></ul></div>"},{"i":"84c13edd47c2","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quel est l'intérêt du dosage des β-hCG chez la femme en âge de procréer lors d'une suspicion d'appendicite aiguë ?","a":"<div class=\"notion-course\"><p>Le dosage des <strong><span class=\"nc-pink nc-bold\">β-hCG</span></strong> est <span class=\"nc-red nc-bold\">systématique</span> chez toute femme en âge de procréer présentant une douleur abdominale. Il permet d'<strong>écarter une <span class=\"nc-red_bg\">grossesse extra-utérine</span></strong> (GEU), mais n'apporte aucune information sur l'appendice lui-même.</p></div>"},{"i":"d81bb399f744","n":356,"o":"356-15","u":"Examens complémentaires","t":"Connaître les examens biologiques à demander et leurs limites","q":"Quel est l'intérêt général du bilan biologique dans le diagnostic de l'appendicite aiguë selon le contexte de l'EDN ?","a":"<div class=\"notion-course\"><p>En contexte d'EDN, le bilan biologique pour l'appendicite aiguë <strong>conforte le diagnostic</strong> et <strong>écarte certains diagnostics différentiels</strong>, mais il ne permet jamais de poser le diagnostic à lui seul. Son apport reste <strong>limité</strong>.</p></div>"},{"i":"01b85b508ca5","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Quelles sont les limites principales de l'échographie et de la TDM dans le diagnostic de l'appendicite aiguë, et quel examen est préféré chez la femme enceinte ?","a":"<div class=\"notion-course\"><ul><li>Les limites de l'<span class=\"nc-blue_bg\">échographie</span> sont qu'elle est <strong>opérateur-dépendante</strong> et sa mise en défaut chez l'<strong>obèse</strong> ou si l'appendice est <strong><span class=\"nc-red nc-bold\">rétro-caecal</span></strong>.</li><li>Les limites de la TDM sont son caractère <strong>irradiant</strong> et l'utilisation de <strong>produit de contraste iodé</strong>.</li><li>Chez la <span class=\"nc-pink nc-bold\">femme</span> <span class=\"nc-pink nc-bold\">enceinte</span>, l'<strong>IRM abdominale</strong> est préférée, bien que moins disponible en urgence.</li></ul></div>"},{"i":"1041534109e9","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Quel est l'examen d'imagerie de première intention pour confirmer une appendicite aiguë et quels sont ses principaux critères diagnostiques échographiques ?","a":"<div class=\"notion-course\"><p>L'examen d'<span class=\"nc-green nc-bold\">imagerie</span> de première intention est l'<strong><span class=\"nc-blue_bg\">échographie abdominale</span></strong>.</p><ul><li>Diamètre de l'appendice <strong>supérieur ou égal à 6 mm</strong>.</li><li>Paroi de l'appendice <strong>supérieure à 3 mm</strong>.</li><li>Appendice <strong><span class=\"nc-orange nc-bold\">incompressible</span></strong> et <strong><span class=\"nc-orange nc-bold\">douloureux</span></strong><span class=\"nc-orange nc-bold\"> au passage de la sonde</span>.</li><li><span class=\"nc-blue_bg\">Aspect en </span><strong><span class=\"nc-blue_bg\">cocarde</span></strong>, perte de la différenciation des couches pariétales.</li><li><strong>Infiltration <span class=\"nc-blue nc-bold\">hyperéchogène</span> de la graisse</strong> péri-appendiculaire.</li><li>Présence d'un <strong>stercorite avec cône d'ombre</strong>.</li></ul></div>"},{"i":"443b9384700d","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Dans quel contexte la TDM abdomino-pelvienne injectée est-elle indiquée pour l'appendicite aiguë et quels sont ses principaux critères diagnostiques ?","a":"<div class=\"notion-course\"><p>La TDM abdomino-pelvienne injectée est indiquée en cas de <strong><span class=\"nc-red nc-bold\">complication</span></strong>, de <strong><span class=\"nc-red nc-bold\">doute</span> <span class=\"nc-red nc-bold\">diagnostique</span></strong>, ou chez le <strong><span class=\"nc-red nc-bold\">sujet</span> <span class=\"nc-red nc-bold\">âgé</span> ou obèse</strong>.</p><ul><li>Diamètre de l'appendice <strong>supérieur ou égal à 8 mm</strong>.</li><li><strong>Épaississement pariétal</strong>.</li><li><strong>Infiltration systématique de la graisse péri-appendiculaire</strong>.</li><li>Stécorite éventuel.</li></ul></div>"},{"i":"5ceac051b954","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Quelles complications de l'appendicite aiguë peuvent être recherchées spécifiquement par l'échographie et la TDM abdominale ?","a":"<div class=\"notion-course\"><ul><li>L'<strong><span class=\"nc-blue_bg\">échographie</span></strong> peut rechercher un <strong>épanchement liquidien</strong> et un <strong>abcès</strong> (ainsi que nécrose et <span class=\"nc-red\">plastron</span> selon le collège de pédiatrie).</li><li>La <strong>TDM-AP injectée</strong> peut rechercher un <strong>abcès</strong>, un <strong>épanchement péri-hépatique</strong>, un <strong>épanchement du cul-de-sac de Douglas</strong> et un <strong>épanchement de la cavité péritonéale</strong>.</li></ul></div>"},{"i":"84796d601b04","n":356,"o":"356-16","u":"Examens complémentaires","t":"Connaître les examens d’imagerie à demander et leurs limites","q":"Comment l'imagerie s'intègre-t-elle dans la stratégie diagnostique de l'appendicite aiguë selon la probabilité clinique (stratégie HAS 2012) chez un patient avec une probabilité intermédiaire ?","a":"<div class=\"notion-course\"><p>Pour une probabilité intermédiaire, caractérisée par la présence d'<strong>un ou deux éléments de la triade</strong> (<span class=\"nc-blue_bg\">défense en FID</span>, <span class=\"nc-blue_bg\">hyperleucocytose</span> <span class=\"nc-red nc-bold\">&gt; 10 G/L</span>, <span class=\"nc-blue_bg\">CRP</span> <span class=\"nc-red nc-bold\">&gt; 8 mg/L</span>), une <strong>imagerie morphologique au minimum (<span class=\"nc-blue_bg\">échographie</span> ou <span class=\"nc-blue_bg\">TDM</span>)</strong> est recommandée, avec une hospitalisation prolongée avant décision.</p></div>"},{"i":"b64fa56c4448","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quelles sont les complications post-opératoires possibles de l'appendicectomie ?","a":"<div class=\"notion-course\"><ul><li><strong>Complications infectieuses</strong> : <span class=\"nc-purple_bg\">infection du site opératoire</span>, <span class=\"nc-red\">abcès</span> de paroi, <span class=\"nc-red\">abcès</span> du cul-de-sac de Douglas, ou péritonite post-opératoire par lâchage du moignon appendiculaire.</li><li><strong>Complications hémorragiques</strong> : <span class=\"nc-blue_bg\">hémorragie</span>, <span class=\"nc-blue_bg\">hématome de paroi</span>.</li><li><strong>Complications digestives</strong> : récidive d'appendicite si moignon appendiculaire trop long (<span class=\"nc-red nc-bold\">appendicectomie incomplète</span>), occlusion du grêle (précoce par <span class=\"nc-red nc-bold\">iléus réflexe</span>, ou tardive sur brides ou éventration).</li></ul></div>"},{"i":"c97a80d17fae","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quel est le traitement de première intention d'une appendicite aiguë non compliquée et quelles sont les voies d'abord chirurgicales ?","a":"<div class=\"notion-course\"><ul><li>Appendicite non compliquée : <span class=\"nc-pink_bg\">appendicectomie</span>, habituellement par cœlioscopie, après diagnostic suffisamment étayé et préparation anesthésique. Antalgie, hydratation adaptée et antibioprophylaxie selon protocole.</li><li>Une stratégie par antibiotiques seuls peut être discutée chez certains patients sélectionnés, avec information sur échec/récidive ; elle ne se substitue pas au contrôle urgent d’une forme compliquée.</li></ul></div>"},{"i":"cd14687831f9","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quels sont les principes et le déroulement de l'appendicectomie pour une appendicite aiguë non compliquée ?","a":"<div class=\"notion-course\"><ul><li>Appendicite non compliquée : <span class=\"nc-pink_bg\">appendicectomie</span>, habituellement par cœlioscopie, après diagnostic suffisamment étayé et préparation anesthésique. Antalgie, hydratation adaptée et antibioprophylaxie selon protocole.</li><li>Analyse anatomopathologique de la pièce pour confirmer et rechercher une tumeur. Pas de drainage ou de lavage péritonéal <span class=\"nc-red nc-bold\">systématique</span> d’une forme simple.</li><li>Après contrôle d’une appendicite non compliquée, ne pas prolonger systématiquement les antibiotiques 24–48 heures au titre d’une prophylaxie. Reprise alimentaire et sortie selon récupération clinique.</li></ul></div>"},{"i":"dd4143974f46","n":356,"o":"356-17","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique de l’appendicite aiguë non compliquée","q":"Quelle est la prise en charge pré-opératoire et les suites habituelles de l'appendicectomie pour une appendicite aiguë non compliquée ?","a":"<div class=\"notion-course\"><ul><li>Appendicite non compliquée : <span class=\"nc-pink_bg\">appendicectomie</span>, habituellement par cœlioscopie, après diagnostic suffisamment étayé et préparation anesthésique. Antalgie, hydratation adaptée et antibioprophylaxie selon protocole.</li><li>Analyse anatomopathologique de la pièce pour confirmer et rechercher une tumeur. Pas de drainage ou de lavage péritonéal <span class=\"nc-red nc-bold\">systématique</span> d’une forme simple.</li><li>Après contrôle d’une appendicite non compliquée, ne pas prolonger systématiquement les antibiotiques 24–48 heures au titre d’une prophylaxie. Reprise alimentaire et sortie selon récupération clinique.</li></ul></div>"},{"i":"29621167bac3","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quelle est la principale complication de l'appendicite aiguë chez l'enfant et à quoi est-elle due ?","a":"<div class=\"notion-course\"><ul><li>Les complications pédiatriques sont <span class=\"nc-red\">plastron</span>, <span class=\"nc-red\">abcès</span> et <span class=\"nc-red_bg\">perforation</span> avec péritonite localisée ou généralisée ; elles sont particulièrement fréquentes chez le très jeune <span class=\"nc-pink nc-bold\">enfant</span> et lorsque le diagnostic est retardé.</li></ul></div>"},{"i":"382916912bf3","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quel est le principal facteur favorisant la perforation appendiculaire pédiatrique ?","a":"<div class=\"notion-course\"><p>Le principal facteur favorisant la perforation appendiculaire pédiatrique est le <strong>retard diagnostique</strong>.</p></div>"},{"i":"4d2973cb9095","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quelle est la fréquence de l'appendicite perforée chez l'enfant par rapport à l'adulte ?","a":"<div class=\"notion-course\"><ul><li>Les complications pédiatriques sont <span class=\"nc-red\">plastron</span>, <span class=\"nc-red\">abcès</span> et <span class=\"nc-red_bg\">perforation</span> avec péritonite localisée ou généralisée ; elles sont particulièrement fréquentes chez le très jeune <span class=\"nc-pink nc-bold\">enfant</span> et lorsque le diagnostic est retardé.</li><li>Ne pas attribuer un taux de <span class=\"nc-red_bg\">perforation</span> de 70–80 % à tous les enfants : il varie fortement avec l’âge et le contexte. Une forme <span class=\"nc-red nc-bold\">non</span> compliquée est possible avant six ans.</li></ul></div>"},{"i":"af2d245b2324","n":356,"o":"356-3","u":"Suivi et/ou pronostic","t":"Connaître les complications chez l’enfant","q":"Quel est l'impact de l'âge sur le risque de complication de l'appendicite chez l'enfant ?","a":"<div class=\"notion-course\"><ul><li>Les complications pédiatriques sont <span class=\"nc-red\">plastron</span>, <span class=\"nc-red\">abcès</span> et <span class=\"nc-red_bg\">perforation</span> avec péritonite localisée ou généralisée ; elles sont particulièrement fréquentes chez le très jeune <span class=\"nc-pink nc-bold\">enfant</span> et lorsque le diagnostic est retardé.</li><li>Ne pas attribuer un taux de <span class=\"nc-red_bg\">perforation</span> de 70–80 % à tous les enfants : il varie fortement avec l’âge et le contexte. Une forme <span class=\"nc-red nc-bold\">non</span> compliquée est possible avant six ans.</li></ul></div>"},{"i":"107779b2cbfc","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quels sont les délais d'intervention chirurgicale recommandés pour l'appendicite aiguë en fonction de la situation clinique ?","a":"<div class=\"notion-course\"><ul><li>Forme non compliquée confirmée : prise en charge chirurgicale précoce, généralement dans les 24 heures selon organisation. Péritonite, sepsis ou instabilité : urgence renforcée, réanimation et contrôle de foyer sans retard.</li></ul></div>"},{"i":"3c10d800c326","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quelle a été l'évolution de la doctrine concernant l'indication de l'appendicectomie ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-pink_bg\">appendicectomie</span> n'est plus <span class=\"nc-red nc-bold\">systématique</span> devant toute douleur de la fosse iliaque droite. Elle est décidée uniquement après une <strong>démarche diagnostique structurée</strong> incluant clinique, biologie et <span class=\"nc-green nc-bold\">imagerie</span>.</p></div>"},{"i":"4d8833bdffe3","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quelles sont les mesures pré-opératoires essentielles à mettre en place face à une appendicite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Mesures initiales : jeûne, antalgie suffisante, hydratation adaptée, antibiotiques selon forme et protocole, consultation anesthésique.</li></ul></div>"},{"i":"b7ba0cd9192d","n":356,"o":"356-5","u":"Prise en charge","t":"Connaître les principes de prise en charge","q":"Quel est le principe général de prise en charge chirurgicale d'une appendicite aiguë confirmée ?","a":"<div class=\"notion-course\"><ul><li>L’<span class=\"nc-pink_bg\">appendicectomie</span> reste le <span class=\"nc-pink_bg\">traitement</span> de référence. La décision repose sur probabilité clinique, biologie et imagerie adaptée ; toute douleur de fosse iliaque droite n’est pas une indication opératoire.</li><li>Certaines formes non compliquées sélectionnées ou abcès/plastrons peuvent relever d’un traitement initial non opératoire ; bénéfices, récidive et surveillance sont discutés par l’équipe. Ne pas présenter cette option comme adaptée à tous ni comme inexistante.</li></ul></div>"},{"i":"43e0791c1124","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quelle est la physiopathologie de l'appendicite aiguë en l'absence de traitement ?","a":"<div class=\"notion-course\"><p>L'obstruction initiale entraîne une <strong>pullulation microbienne</strong> et l'infection de l'appendice. L'inflammation gagne les <span class=\"nc-orange_bg\">4 couches pariétales</span> (<span class=\"nc-red nc-bold\">appendicite </span><strong><span class=\"nc-red nc-bold\">suppurée</span></strong>), la distension comprime la vascularisation et entraîne une <strong><span class=\"nc-red nc-bold\">ischémie artérielle</span></strong>. L'évolution se fait ensuite vers la <strong><span class=\"nc-purple nc-bold\">gangrène</span></strong> puis la <strong><span class=\"nc-red nc-bold\">perforation</span></strong> si elle n'est pas traitée.</p></div>"},{"i":"4a4656921cee","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quels sont les autres mécanismes pouvant entraîner une obstruction appendiculaire et provoquer une appendicite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Une <strong>infection parasitair</strong>e (ex : ascaris).</li><li>Une <strong><span class=\"nc-brown_bg\">sténose inflammatoire</span></strong> (ex : maladie de <span class=\"nc-red nc-bold\">Crohn</span>).</li><li>Une <strong><span class=\"nc-red nc-bold\">tumeur</span></strong> (le plus souvent carcinoïde).</li></ul></div>"},{"i":"68a14fc18322","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quelles sont les causes les plus classiques de l'obstruction de la lumière appendiculaire dans l'appendicite aiguë ?","a":"<div class=\"notion-course\"><ul><li>Le <strong><span class=\"nc-red nc-bold\">stercolithe</span></strong> (concrétion dure de matières fécales).</li><li>L'<strong>hyperplasie lymphoïde</strong> (réaction des <span class=\"nc-green\">follicules</span> <span class=\"nc-green\">lymphoïdes</span> à un <span class=\"nc-red nc-bold\">épisode</span> viral ou bactérien).</li></ul></div>"},{"i":"afcb80518da7","n":356,"o":"356-7","u":"Définition","t":"Connaître la définition de l’appendicite aiguë","q":"Quelle est la définition de l'appendicite aiguë ?","a":"<div class=\"notion-course\"><p>L'appendicite aiguë est une <strong>inflammation aiguë de l'appendice vermiforme</strong>, le plus souvent secondaire à une <strong>obstruction de sa lumière appendiculaire</strong>.</p></div>"},{"i":"cedea5afcc9d","n":356,"o":"356-9","u":"Diagnostic positif","t":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","q":"Quelles sont les caractéristiques principales de la douleur appendiculaire typique de l'appendicite aiguë ?","a":"<div class=\"notion-course\"><p>La douleur appendiculaire typique est une douleur :</p><ul><li>De mode de début <strong>brutal</strong>.</li><li>Qui débute en région <strong>épigastrique ou <span class=\"nc-blue_bg\">péri-ombilicale</span></strong>, puis <strong>migre en fosse iliaque droite</strong> <span class=\"nc-pink nc-bold\">en quelques heures</span>.</li><li><strong><span class=\"nc-yellow_bg\">Permanente</span></strong>, d'intensité croissante sur les premières 24h.</li><li>De type <strong>torsion ou crampe</strong>.</li><li><strong>Majorée</strong> par les <span class=\"nc-red nc-bold\">mouvements</span>, la <span class=\"nc-red nc-bold\">toux</span> et le <span class=\"nc-red nc-bold\">cloche-pied droit</span>.</li></ul></div>"},{"i":"d8ec01d9d661","n":356,"o":"356-9","u":"Diagnostic positif","t":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","q":"Quels sont les signes digestifs et généraux souvent associés à la douleur dans un tableau typique d'appendicite aiguë ?","a":"<div class=\"notion-course\"><p>Les signes associés sont :</p><ul><li><strong>Signes digestifs</strong> : <span class=\"nc-blue_bg\">nausées</span>, <span class=\"nc-blue_bg\">vomissements</span>, <span class=\"nc-brown_bg\">inappétence</span>, <span class=\"nc-blue_bg\">diarrhée</span> (rare).</li><li><strong>Signes généraux</strong> : <strong><span class=\"nc-blue_bg\">fébricule</span> à 37,5-38,5 °C</strong> (dans 60% des cas), parfois absent ; et en cas de formes évoluées, des <span class=\"nc-brown_bg\">signes de déshydratation</span> (tachycardie, pli cutané, langue saburrale).</li></ul></div>"},{"i":"f121b1762105","n":356,"o":"356-9","u":"Diagnostic positif","t":"Connaître les signes d’appel et les caractéristiques de la douleur appendiculaire typique","q":"Quels sont les principaux signes à rechercher à l'examen physique de la fosse iliaque droite évoquant une appendicite aiguë ?","a":"<div class=\"notion-course\"><p>Les signes à rechercher sont :</p><ul><li>Le <strong>point de <span class=\"nc-red_bg nc-bold\">McBurney</span></strong> positif : douleur provoquée (sensibilité ou défense) au 1/3 externe de la ligne reliant l'épine iliaque antéro-supérieure droite à l'ombilic.</li><li>Le <strong><span class=\"nc-yellow_bg\">signe de Blumberg</span></strong> : douleur en FID à la décompression brutale (inconstant).</li><li>Le <strong><span class=\"nc-yellow_bg\">signe de Rovsing</span></strong> : douleur en FID provoquée par la compression de la fosse iliaque gauche (inconstant).</li><li>Le <strong><span class=\"nc-red_bg\">psoïtis</span></strong> : <span class=\"nc-red nc-bold\">boiterie</span>, cuisse droite fléchie, douleur majorée par l'<span class=\"nc-red nc-bold\">extension de la cuisse sur le bassin</span>.</li><li>Le <strong><span class=\"nc-yellow_bg\">Heel drop test</span></strong> : douleur abdominale déclenchée par la retombée sur les talons.</li><li>Au <strong>toucher <span class=\"nc-red nc-bold\">rectal</span></strong> : douleur latéralisée à droite (cri du Douglas).</li></ul></div>"},{"i":"862a773aa2a9","n":356,"o":"356-2","u":"Epidémiologie","t":"Connaître les âges de survenue","q":"Quels sont les points essentiels concernant les âges de survenue ?","a":"<div class=\"notion-course\"><p>L'<span>appendicite</span> aiguë peut survenir <strong>à tout âge</strong>, mais sa <span class=\"nc-brown_bg\">fréquence</span> suit une distribution caractéristique.</p>\n      <ul>\n        <li>Pic de <span class=\"nc-brown_bg\">fréquence</span> : de <span><span class=\"nc-yellow_bg nc-bold\">6 ans</span></span> à <span><span class=\"nc-yellow_bg nc-bold\">30-40 ans</span></span>, avec une atteinte maximale chez l'<span><span class=\"nc-pink_bg\">adolescent</span></span> et le <span>jeune adulte</span> (<span>2ᵉ et 3ᵉ décennies</span>).</li>\n        <li><span>Exceptionnelle</span> avant <span>1 an</span> ; <span><span class=\"nc-brown_bg\">rare</span></span><span class=\"nc-brown_bg\"> avant</span> <span>3 ans</span>.</li>\n        <li>La <span class=\"nc-brown_bg\">fréquence</span> <strong><span class=\"nc-brown_bg nc-bold\">décroît avec l'âge</span></strong> au-delà de <span>40 ans</span>, du fait de l'<span><span class=\"nc-brown_bg nc-bold\">involution des tissus lymphoïdes</span></span> appendiculaires.</li>\n        <li>Dans la tranche <span>20-40 ans</span>, légère <span><span class=\"nc-pink nc-bold\">prédominance masculine</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège des âges extrêmes :</strong> chez le <span>nourrisson</span>, la pauvreté des <span>tissus <span class=\"nc-green\">lymphoïdes</span></span> rend l'<span>appendicite</span> <span>rare mais d'emblée grave</span> ; chez le <span>sujet <span class=\"nc-red nc-bold\">âgé</span></span>, une douleur de la <span>fosse iliaque droite</span> impose d'évoquer par principe un <span>cancer du côlon droit</span> avant de retenir une appendicite.</div></div>"},{"i":"5482966cff21","n":356,"o":"356-4","u":"Examens complémentaires","t":"Connaître l’intérêt et les limites des examens complémentaires","q":"Quels sont les points essentiels concernant l’intérêt et les limites des examens complémentaires ?","a":"<div class=\"notion-course\"><p>Le diagnostic d'<span>appendicite</span> reste <strong>avant tout clinique</strong>. <span>Les</span> examens complémentaires servent à <strong>conforter</strong> le diagnostic, <strong>éliminer un <span>diagnostic différentiel</span></strong> ou <strong>dépister une <span class=\"nc-red nc-bold\">complication</span></strong> — jamais à remplacer l'examen.</p>\n      <table>\n        <thead>\n          <tr><th>Examen</th><th>Intérêt</th><th>Limites</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-yellow_bg\">NFS</span></span></td>\n            <td>Marqueur le plus souvent perturbé : <span>hyperleucocytose à PNN</span> dans plus de <span>80 %</span> des cas.</td>\n            <td>Peut être normale dans <span>les</span> formes débutantes ; <span class=\"nc-red nc-bold\">non</span> <span class=\"nc-red nc-bold\">spécifique</span>.</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-yellow_bg\">CRP</span></span></td>\n            <td>Témoigne d'une inflammation évoluant depuis quelques heures.</td>\n            <td><span><span class=\"nc-green nc-bold\">Normale dans 50 %</span></span><span class=\"nc-green nc-bold\"> des cas</span> (<span>appendicite</span> <span class=\"nc-green_bg\">catarrhale</span> débutante).</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-brown_bg\">Bandelette urinaire</span></span></td>\n            <td>Élimine une <span><span class=\"nc-orange_bg\">infection urinaire</span></span>.</td>\n            <td>Une <span>leucocyturie</span> modérée peut accompagner une <span>appendicite</span> pelvienne (piège).</td>\n          </tr>\n          <tr><td colspan=\"7\">Un test de grossesse fait partie du bilan selon possibilité de grossesse ; sa positivité impose de localiser la grossesse. Le dosage ne permet pas, à lui seul, d’écarter une GEU.</td></tr>\n          <tr>\n            <td><span><span class=\"nc-blue_bg\">Échographie abdominale</span></span></td>\n            <td>Examen de <strong>1ʳᵉ intention</strong> ; <span>Se ≈ 80 %</span> ; non irradiante.</td>\n            <td>Opérateur-dépendante ; mise en défaut chez l'<span>obèse</span> et si appendice <span><span class=\"nc-red nc-bold\">rétro-caecal</span></span>.</td>\n          </tr>\n          <tr>\n            <td><span>TDM abdomino-pelvienne injectée</span></td>\n            <td>Meilleure performance (<span>Se et Sp &gt; 90-95 %</span>) ; précise <span>les</span> complications.</td>\n            <td>Irradiante ; réservée au <span class=\"nc-red nc-bold\">doute</span>, à la <span class=\"nc-red nc-bold\">complication</span>, au <span class=\"nc-red nc-bold\">sujet</span> <span class=\"nc-red nc-bold\">âgé</span> ou obèse.</td>\n          </tr>\n          <tr>\n            <td><span>IRM abdominale</span></td>\n            <td>Alternative non irradiante chez la <span><span class=\"nc-pink nc-bold\">femme</span> <span class=\"nc-pink nc-bold\">enceinte</span></span>.</td>\n            <td>Peu disponible en <span>urgence</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Examens à ne pas demander :</strong> l'<span>ASP</span> n'a plus aucune place dans le bilan d'<span>appendicite</span> ; le dosage de <span>procalcitonine</span> n'est pas recommandé car il n'améliore pas la précision <span class=\"nc-red nc-bold\">diagnostique</span>.</div></div>"},{"i":"75b65c67b4c0","n":356,"o":"356-6","u":"Diagnostic positif","t":"Connaître la symptomatologie de l’appendicite chez le nourrisson","q":"Quels sont les points essentiels concernant la symptomatologie de l’appendicite chez le nourrisson ?","a":"<div class=\"notion-course\"><p>Chez le <span>nourrisson</span>, la présentation est <span><span class=\"nc-red nc-bold\">non</span> <span class=\"nc-red nc-bold\">spécifique</span> et <span class=\"nc-red nc-bold\">trompeuse</span></span>. C'est ce qui fait toute la <span>gravité</span> de la pathologie à cet âge : le diagnostic est porté <span>tardivement</span>.</p>\n      <ul>\n        <li><span>Altération de l'état général</span> (<span>AEG</span>).</li>\n        <li><span><span class=\"nc-blue_bg\">Fièvre</span></span> et <span><span class=\"nc-blue_bg\">vomissements</span></span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Diarrhée</span></span> — qui oriente faussement vers une <span>gastro-entérite</span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Distension abdominale</span></span> et <span><span class=\"nc-blue_bg\">déshydratation</span></span>.</li>\n        <li><span><span class=\"nc-yellow_bg\">Agitation</span></span> et <span><span class=\"nc-yellow_bg\">insomnie</span></span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">Chez le nourrisson, une suspicion persistante impose des réévaluations rapprochées et un avis chirurgical ; ne pas proposer d’attendre plusieurs jours devant des signes de <span class=\"nc-red nc-bold\">complication</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 269 — <span>Douleur abdominale</span> aiguë</em></p></div>"},{"i":"b2ca4f1309e3","n":356,"o":"356-8","u":"Epidémiologie","t":"Connaître la fréquence, l’âge de survenue et la morbi-mortalité et la mortalité de l’appendicite","q":"Quels sont les points essentiels concernant la fréquence, l’âge de survenue et la morbi-mortalité et la mortalité de l’appendicite ?","a":"<div class=\"notion-course\"><p>L'<span>appendicite</span> aiguë est l'<span><span class=\"nc-yellow_bg\">urgence abdominale la plus fréquente</span></span>.</p>\n      <ul>\n        <li><strong>Fréquence :</strong> concerne environ <span>7 %</span> de la population dans <span>les</span> pays occidentaux, dont <span>20 %</span> de <span>formes compliquées</span>.</li>\n        <li><strong>Volume d'activité :</strong> environ <span>90 000 à 130 000</span> <span>appendicectomies</span> par an en France (<span>≈ 1,4 / 1 000 habitants</span>), soit <span>≈ 30 %</span> des interventions de <span>chirurgie</span> digestive.</li>\n        <li><strong>Âge :</strong> pic de <span class=\"nc-brown_bg\">fréquence</span> de <span><span class=\"nc-yellow_bg nc-bold\">6 ans</span></span> à <span><span class=\"nc-yellow_bg nc-bold\">30-40 ans</span></span> ; exceptionnelle avant <span>1 an</span>, <span class=\"nc-brown_bg\">rare avant</span> <span>3 ans</span> ; décroît ensuite avec l'âge.</li>\n      </ul>\n\n      <h5>Morbi-<span>mortalité</span></h5>\n      <table>\n        <thead>\n          <tr><th>Indicateur</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span>Mortalité</span> post-opératoire globale</td><td><span>&lt; 0,5 %</span></td></tr>\n          <tr><td><span>Mortalité</span> — forme non compliquée</td><td><span>≈ 0,1 %</span></td></tr>\n          <tr><td><span>Mortalité</span> — <span>perforation appendiculaire</span></td><td><span>≈ 1,5 %</span></td></tr>\n          <tr><td><span>Morbidité</span> globale des <span>appendicectomies</span></td><td><span>≈ 10 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong><span>Évolution</span> des pratiques :</strong> l'<span><span class=\"nc-pink_bg\">appendicectomie</span></span> était autrefois quasi <span class=\"nc-red nc-bold\">systématique</span> devant toute douleur de la <span>fosse iliaque droite</span> ; elle n'est aujourd'hui réalisée qu'au terme d'une démarche <span class=\"nc-red nc-bold\">diagnostique</span>.</div></div>"},{"i":"913e903ff377","n":356,"o":"356-11","u":"Diagnostic positif","t":"Connaître les variations anatomiques de l’appendice et les formes cliniques qui en résultent","q":"Quels sont les points essentiels concernant les variations anatomiques de l’appendice et les formes cliniques qui en résultent ?","a":"<div class=\"notion-course\"><p><span>Les</span> variations de position de l'<span>appendice vermiforme</span> (et du cæcum) sont fréquentes et expliquent l'extrême variabilité des présentations cliniques.</p>\n\n      <h5><span class=\"nc-brown_bg\">Fréquence</span> des localisations anatomiques</h5>\n      <table>\n        <thead>\n          <tr><th>Localisation</th><th>Fréquence</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span><span class=\"nc-red nc-bold\">Latéro-caecale</span></span> (face postéro-médiale du cæcum)</td><td><span>≈ 70 %</span></td></tr>\n          <tr><td><span>Rétro-caecale</span></td><td><span>≈ 25 %</span></td></tr>\n          <tr><td><span>Pelvienne</span></td><td><span>≈ 5 %</span></td></tr>\n          <tr><td><span><span class=\"nc-red nc-bold\">Méso-cœliaque</span></span> (pré- ou rétro-iléale) et <span><span class=\"nc-red nc-bold\">sous-hépatique</span></span></td><td>Rares</td></tr>\n          <tr><td>Fosse iliaque gauche (<span>mésentère commun</span>)</td><td>Exceptionnelle</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Formes cliniques résultant de la topographie</h5>\n      <table>\n        <thead>\n          <tr><th>Localisation</th><th>Présentation</th><th>Confirmation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Rétro-caecale</span></td>\n            <td><span><span class=\"nc-red_bg\">Psoïtis</span></span> franc ; douleur peu marquée en FID, plutôt en <span>flanc droit</span> ; <span class=\"nc-red nc-bold\">palper bimanuel</span> en <span class=\"nc-red nc-bold\">décubitus latéral gauche</span>.</td>\n            <td><span><span class=\"nc-blue_bg\">TDM injectée</span></span></td>\n          </tr>\n          <tr>\n            <td><span>Pelvienne</span></td>\n            <td>Douleur hypogastrique droite ; <span>signes urinaires</span> (<span>pollakiurie</span>, <span>dysurie</span>) ; <span><span class=\"nc-red nc-bold\">ténesme</span> <span class=\"nc-red nc-bold\">rectal</span></span> et <span class=\"nc-red nc-bold\">faux besoins</span> ; toucher <span class=\"nc-red nc-bold\">rectal</span> et vaginal contributifs.</td>\n            <td><span><span class=\"nc-blue_bg\">Échographie pelvienne</span></span></td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Méso-cœliaque</span></span></td>\n            <td><span class=\"nc-red_bg\">Tableau d'</span><span><span class=\"nc-red_bg\">occlusion fébrile</span></span> par <span><span class=\"nc-red nc-bold\">iléus</span></span><span class=\"nc-red nc-bold\"> réflexe</span> au <span>contact</span> des anses.</td>\n            <td><span>Imagerie</span> voire intervention</td>\n          </tr>\n          <tr>\n            <td><span><span class=\"nc-red nc-bold\">Sous-hépatique</span></span></td>\n            <td>Tableau pseudo-<span><span class=\"nc-orange_bg\">cholécystite</span></span> : douleur et défense de l'hypochondre droit avec <span><span class=\"nc-blue_bg\">fièvre</span></span>.</td>\n            <td><span>Échographie</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège :</strong> la forme <span class=\"nc-red nc-bold\">méso-cœliaque</span> réalise un véritable tableau de syndrome occlusif fébrile qui peut faire errer le diagnostic.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 354 — Syndrome occlusif</em></p></div>"},{"i":"56a6d24f8c79","n":356,"o":"356-12","u":"Diagnostic positif","t":"Connaître les particularités de la présentation clinique de l’appendicite chez la femme enceinte","q":"Quels sont les points essentiels concernant les particularités de la présentation clinique de l’appendicite chez la femme enceinte ?","a":"<div class=\"notion-course\"><p>Chez la <span>femme <span class=\"nc-pink nc-bold\">enceinte</span></span>, la présentation dépend du <strong>terme</strong> de la <span>grossesse</span>, l'utérus gravide refoulant progressivement l'appendice.</p>\n      <table>\n        <thead>\n          <tr><th>Terme</th><th>Présentation clinique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>1ᵉʳ trimestre</span></td>\n            <td>Examen clinique <strong>non modifié</strong> : tableau d'<span>appendicite</span> en situation normale.</td>\n          </tr>\n          <tr>\n            <td><span>2ᵉ et 3ᵉ trimestres</span></td>\n            <td>L'<span>augmentation du volume utérin</span> <strong>refoule l'<span>appendice</span> vers l'<span>hypochondre droit</span></strong> (vers le <strong>haut</strong>, le <strong>dehors</strong> et l'<strong>arrière</strong>) : <span><span class=\"nc-blue_bg\">douleur ascensionnée</span></span><span class=\"nc-blue_bg\"> ou </span><span><span class=\"nc-blue_bg\">diffuse</span></span> ; <span><span class=\"nc-blue_bg\">contractures utérines</span></span> parfois au premier plan ; <span><span class=\"nc-green nc-bold\">absence de défense</span></span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Diagnostics différentiels :</strong> <span><span class=\"nc-orange_bg\">infection urinaire</span></span> ; <span><span class=\"nc-orange_bg\">cholécystite</span></span>.</li>\n        <li><strong>Imagerie :</strong> l'<span>IRM abdominale</span> est <span>préférée à la TDM</span> (caractère <span>non irradiant</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège :</strong> l'<span><span class=\"nc-green nc-bold\">absence de défense</span></span> aux 2ᵉ et 3ᵉ trimestres ne doit jamais faire éliminer une <span>appendicite</span> — la <span>position ectopique de l'appendice</span> masque <span>les</span> <span>signes pariétaux</span> classiques.</div></div>"},{"i":"d428e9305894","n":356,"o":"356-13","u":"Diagnostic positif","t":"Connaître les particularités de la présentation clinique de l’appendicite chez le sujet âgé","q":"Quels sont les points essentiels concernant les particularités de la présentation clinique de l’appendicite chez le sujet âgé ?","a":"<div class=\"notion-course\"><p>Chez le <span>sujet <span class=\"nc-red nc-bold\">âgé</span></span>, l'<span>appendicite</span> est <span>plus rare</span> mais souvent <span>diagnostiquée tardivement</span>, à un <span>stade compliqué</span>.</p>\n      <ul>\n        <li><span>Symptômes <span class=\"nc-red nc-bold\">moins</span> <span class=\"nc-red nc-bold\">francs</span></span> que chez l'<span>adulte jeune</span>.</li>\n        <li><span>Évolution <span class=\"nc-red nc-bold\">plus torpide</span></span>.</li>\n        <li><span>Iléus</span> fréquemment présent.</li>\n        <li><span>Indice de perforation élevé</span> (<span>≈ 30 %</span>) du fait du <span>retard diagnostique</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\">Chez le <span class=\"nc-pink nc-bold\">sujet âgé</span>, rechercher une <span class=\"nc-red nc-bold\">tumeur</span> cæcale et les autres diagnostics, sans retarder le traitement d’une appendicite compliquée. Organiser les explorations coliques adaptées après l’<span class=\"nc-red nc-bold\">épisode</span> si indiquées.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181a0b21be70009b4c63e?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
